-- Factory acquisition owner and grant contract (docs/factory-acquisition-owner-design.md, PR #314 @458cba5d).
--
-- Slot 052000 is a PROVISIONAL registry assignment; the registry owner may renumber it. Rollback (generated by
-- scripts/sessions-function-boundary/lanes/acquisition-owner.ts):
-- supabase/rollbacks/20261105052000_ingest_acquisition_owner.down.sql. Runbook: docs/ingest-acquisition-owner.md.
--
-- DORMANT BEHIND A FLAG. Applying this changes no answer for any source:
--   * Flag sessions.ingest_acquisition_hooks_switch.enabled (default false; owner-only setter
--     sessions.ingest_acquisition_set_hooks(boolean), no role may call it) gates every hook-side acquisition step.
--     While it is false each replaced hook behaves as its prior body: no enrollment-gate row lock, no advisory
--     lock, no admission and no new failure path, and a request carrying an `acquisition` key is refused as
--     malformed exactly as before. The only residual cost is an ACCESS SHARE relation lock on the one-row switch
--     table (the flag read), which waits only while the owner flips the flag or runs DDL on that table.
--   * sessions.ingest_acquisition_switch.install_enabled is false: every install refuses `disabled`.
--   * enroll_begin refuses `hooks_disabled` until the flag is on, and the flag cannot be turned off while any
--     enrollment row exists, so data alone never arms a hook and an armed source is never silently unprotected.
--   * enroll_begin/enroll_complete/set_hooks are granted to no role; only the owner runs them, under a separate
--     explicit OK. Rollback: the generated rollback refuses (55000) while the flag is on; turn it off first.
--   * bulls96_acquisition_installer (NOLOGIN from the role bootstrap) may run install/revoke/rebind/status only.
--
-- Plain transactional DDL (no CONCURRENTLY: the migrator applies this file in one transaction). The step-8
-- freshness and backfill scans read existing (org_id, workspace_id, ...)
-- primary keys; any extra index they need is a CONCURRENTLY operator step with no slot (design §8.3).
--
-- Every replaced hook below is the CURRENT body (20261104055000 / 20261104060000) with only the acquisition
-- calls inserted; each replaced body is listed in the lane manifest so the rollback restores it byte-for-byte.

-- Fail fast instead of queueing live readers/writers behind a blocked DDL lock (migrate.ts applies
-- each file in one transaction, so SET LOCAL lasts exactly as long as this file).
SET LOCAL lock_timeout='5s';
DO $acquisition_creator$
DECLARE me oid;
BEGIN
 SELECT oid INTO STRICT me FROM pg_roles WHERE rolname=current_user;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='sessions' AND c.relname IN('ingest_claim_attempts','ingest_publication_heads','session_index')
    AND c.relowner<>me)
  OR EXISTS(SELECT 1 FROM pg_proc WHERE oid IN('sessions.ingest_claim_batch_mode(jsonb,text)'::regprocedure,
    'sessions.ingest_claim_buffered_batch(jsonb)'::regprocedure,'sessions.ingest_prepare_buffer_stage(jsonb)'::regprocedure,
    'sessions.ingest_commit_buffered_batch(jsonb)'::regprocedure,'sessions.ingest_commit_batch(jsonb)'::regprocedure,
    'sessions.ingest_publication_claim(jsonb)'::regprocedure,'sessions.ingest_publication_publish(jsonb)'::regprocedure,
    'sessions.ingest_publication_guard_pointer()'::regprocedure) AND proowner<>me) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: owner contract requires original creator';END IF;
END $acquisition_creator$;

-- The control role (supabase/bootstrap/session_ingest_roles.sql, NOLOGIN; LOGIN only by the operator step
-- acquisition_installer_role.sql, which may run before or after this migration). Fail closed if the bootstrap has
-- not provisioned it (42704) or it exists elevated or as a member of another role (55000).
DO $acquisition_role$
DECLARE r pg_roles%ROWTYPE;
BEGIN
 SELECT * INTO r FROM pg_roles WHERE rolname='bulls96_acquisition_installer';
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42704',MESSAGE='acquisition: role bulls96_acquisition_installer absent; run the role bootstrap first';END IF;
 IF r.rolsuper OR r.rolbypassrls OR r.rolinherit OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication
  OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=r.oid) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: role bulls96_acquisition_installer exists elevated or is a member';END IF;
END $acquisition_role$;

-- §3 data model, verbatim from the design.
CREATE TABLE sessions.ingest_acquisition_switch(          -- dormant: install refused until true
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 install_enabled boolean NOT NULL DEFAULT false,changed_at timestamptz NOT NULL DEFAULT clock_timestamp());
INSERT INTO sessions.ingest_acquisition_switch DEFAULT VALUES;
CREATE TABLE sessions.ingest_acquisition_hooks_switch(    -- flag: hook-side acquisition off until true
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 enabled boolean NOT NULL DEFAULT false,changed_at timestamptz NOT NULL DEFAULT clock_timestamp());
INSERT INTO sessions.ingest_acquisition_hooks_switch DEFAULT VALUES;
CREATE TABLE sessions.ingest_acquisition_enrollment_gate( -- §4.8 interlock row; never deleted
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0));
INSERT INTO sessions.ingest_acquisition_enrollment_gate DEFAULT VALUES;
CREATE TABLE sessions.ingest_acquisition_enrollment(      -- protected (org,ws,source); absent = main behavior
 org_id text NOT NULL,workspace_id text NOT NULL,source text NOT NULL,
 state text NOT NULL CHECK(state IN('enrolling','enrolled')),PRIMARY KEY(org_id,workspace_id,source),
 backfill_sha256 text CHECK(backfill_sha256~'^[0-9a-f]{64}$'),enrolled_at timestamptz,
 CHECK((state='enrolled')=(backfill_sha256 IS NOT NULL AND enrolled_at IS NOT NULL)));
CREATE TABLE sessions.ingest_acquisition_owners(          -- fence row: never deleted; revision+tombstone live HERE
 org_id text NOT NULL,workspace_id text NOT NULL,source text NOT NULL,session_id text NOT NULL,
 physical_source text NOT NULL,physical_session text NOT NULL,   -- ingest_publication_component() of source/session
 state text NOT NULL CHECK(state IN('unknown','active','draining','released')),
 revision bigint NOT NULL CHECK(revision>=0),                    -- last applied control revision; never decreases
 tombstone_revision bigint CHECK(tombstone_revision>0 AND tombstone_revision<=revision),
 owner_epoch bigint NOT NULL CHECK(owner_epoch>=0),              -- +1 per successful install; never decreases
 grant_id uuid,owner_kind text CHECK(owner_kind IN('cloud','native')),owner_user_id text,owner_origin_id text,
 row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(org_id,workspace_id,source,session_id),
 CHECK((state IN('active','draining'))=(grant_id IS NOT NULL AND owner_kind IS NOT NULL
   AND owner_user_id IS NOT NULL AND owner_origin_id IS NOT NULL)));
CREATE INDEX ingest_acquisition_owners_physical ON sessions.ingest_acquisition_owners(org_id,workspace_id,physical_source,physical_session);
CREATE UNIQUE INDEX ingest_acquisition_owners_physical_live ON sessions.ingest_acquisition_owners  -- §3 collision
 (org_id,workspace_id,physical_source,physical_session) WHERE state IN('active','draining');
CREATE TABLE sessions.ingest_acquisition_grants(          -- the replaceable binding; one row per install
 grant_id uuid PRIMARY KEY,                               -- = the install operation_uuid
 org_id text NOT NULL,workspace_id text NOT NULL,source text NOT NULL,session_id text NOT NULL,
 owner_epoch bigint NOT NULL CHECK(owner_epoch>0),predecessor_grant_id uuid REFERENCES sessions.ingest_acquisition_grants,
 owner_kind text NOT NULL CHECK(owner_kind IN('cloud','native')),owner_user_id text NOT NULL,owner_origin_id text NOT NULL,
 binding_uuid uuid,installation_id uuid,grant_sha256 text NOT NULL UNIQUE CHECK(grant_sha256~'^[0-9a-f]{64}$'),
 evidence_sha256 text NOT NULL CHECK(evidence_sha256~'^[0-9a-f]{64}$'),issuer_key_id text NOT NULL,
 expires_at timestamptz,state text NOT NULL CHECK(state IN('active','draining','released')),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),released_at timestamptz,
 UNIQUE(org_id,workspace_id,source,session_id,owner_epoch),
 FOREIGN KEY(org_id,workspace_id,source,session_id) REFERENCES sessions.ingest_acquisition_owners ON DELETE RESTRICT,
 CHECK((owner_kind='cloud')=(binding_uuid IS NOT NULL AND installation_id IS NULL)),
 CHECK((owner_kind='native')=(installation_id IS NOT NULL AND binding_uuid IS NULL)));
CREATE TABLE sessions.ingest_acquisition_grant_origins(   -- append-only origins of one native grant (§4.7)
 grant_id uuid NOT NULL REFERENCES sessions.ingest_acquisition_grants,origin_id text NOT NULL,
 revision bigint NOT NULL CHECK(revision>0),PRIMARY KEY(grant_id,origin_id));
CREATE TABLE sessions.ingest_acquisition_revoked_grants(  -- revoke-before-install target; immutable
 grant_id uuid PRIMARY KEY,org_id text NOT NULL,workspace_id text NOT NULL,source text NOT NULL,session_id text NOT NULL,
 owner_epoch bigint NOT NULL CHECK(owner_epoch>0),owner_kind text NOT NULL CHECK(owner_kind IN('cloud','native')),
 binding_uuid uuid,installation_id uuid,revision bigint NOT NULL CHECK(revision>0),
 evidence_sha256 text NOT NULL CHECK(evidence_sha256~'^[0-9a-f]{64}$'));
CREATE TABLE sessions.ingest_acquisition_revoked_lineages( -- §4.9 binding-lineage fence; immutable
 org_id text NOT NULL,workspace_id text NOT NULL,source text NOT NULL,session_id text NOT NULL,
 owner_kind text NOT NULL CHECK(owner_kind IN('cloud','native')),lineage_id uuid NOT NULL, -- binding_uuid|installation_id
 revision bigint NOT NULL CHECK(revision>0),PRIMARY KEY(org_id,workspace_id,source,session_id,owner_kind,lineage_id));
CREATE TABLE sessions.ingest_acquisition_operations(      -- idempotency ledger (install/revoke/rebind)
 operation_uuid uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN('install','revoke','rebind')),
 org_id text NOT NULL,workspace_id text NOT NULL,source text NOT NULL,session_id text NOT NULL,
 revision bigint NOT NULL CHECK(revision>0),request_sha256 text NOT NULL CHECK(request_sha256~'^[0-9a-f]{64}$'),
 result jsonb NOT NULL CHECK(jsonb_typeof(result)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
-- Hot tables. Constant defaults: no table rewrite. The CHECKs are added NOT VALID (enforced for every new or updated
-- row; existing rows hold the default and satisfy them), so the ACCESS EXCLUSIVE lock (bounded by lock_timeout
-- above) is not held for a validation scan. The operator runs VALIDATE CONSTRAINT later (SHARE UPDATE EXCLUSIVE,
-- readers and writers keep running); see docs/ingest-acquisition-owner.md.
ALTER TABLE sessions.ingest_claim_attempts ADD COLUMN acquisition jsonb NOT NULL DEFAULT '[]',
 ADD CONSTRAINT ingest_claim_attempts_acquisition_check
  CHECK(jsonb_typeof(acquisition)='array')NOT VALID;       -- admitted [{source,session_id,owner_epoch,grant_id}]
ALTER TABLE sessions.ingest_publication_heads ADD COLUMN acquisition_epoch bigint NOT NULL DEFAULT 0,
 ADD CONSTRAINT ingest_publication_heads_acquisition_epoch_check CHECK(acquisition_epoch>=0)NOT VALID;

ALTER TABLE sessions.ingest_acquisition_switch ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_hooks_switch ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_enrollment_gate ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_enrollment ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_owners ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_grant_origins ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_revoked_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_revoked_lineages ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions.ingest_acquisition_operations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON sessions.ingest_acquisition_switch,sessions.ingest_acquisition_hooks_switch,sessions.ingest_acquisition_enrollment_gate,
 sessions.ingest_acquisition_enrollment,sessions.ingest_acquisition_owners,sessions.ingest_acquisition_grants,
 sessions.ingest_acquisition_grant_origins,sessions.ingest_acquisition_revoked_grants,
 sessions.ingest_acquisition_revoked_lineages,sessions.ingest_acquisition_operations
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder,bulls96_acquisition_installer;

-- ---------------------------------------------------------------------------------------------------------------
-- Owner-only internals (SECURITY INVOKER; EXECUTE revoked from every role). They run only inside the existing
-- SECURITY DEFINER entrypoints and the control functions below, as the owner. Lock order (design §4.5): a hook's
-- existing locks, then LE (gate), then LA, then LP; LA/LP are try-locks and are never waited on.
-- ---------------------------------------------------------------------------------------------------------------

-- §4.5 lock keys. concat_ws keeps an empty workspace in position; identifiers carry no control character.
CREATE FUNCTION sessions.ingest_acquisition_lock_key(p_kind text,p_org text,p_ws text,p_a text,p_b text) RETURNS bigint
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $key$
 SELECT hashtextextended(concat_ws(chr(31),p_kind,p_org,p_ws,p_a,p_b),0)
$key$;

-- §3 grant hash, the only formula (install stores it, admission recomputes it).
CREATE FUNCTION sessions.ingest_acquisition_grant_hash(p_org text,p_ws text,p_source text,p_session text,p_grant_id text,p_grant text)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $hash$
 SELECT encode(sha256(convert_to(concat_ws(chr(31),'relayhistory-acquisition-grant-v1',p_org,p_ws,p_source,p_session,p_grant_id,p_grant),'UTF8')),'hex')
$hash$;

-- §4.8 LE: the gate row FOR SHARE NOWAIT as its own statement, before any enrollment read. Busy (an owner-run
-- enroll_begin holds it) is 40001 session_busy. Under REPEATABLE READ/SERIALIZABLE a gate row updated after the
-- caller's snapshot raises PostgreSQL's own 40001 (not caught here), so a retained snapshot never passes.
CREATE FUNCTION sessions.ingest_acquisition_gate() RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $gate$
BEGIN
 PERFORM 1 FROM sessions.ingest_acquisition_enrollment_gate WHERE singleton FOR SHARE NOWAIT;
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: session_busy';
END $gate$;

-- The flag read, first in every hook-side internal. Statement 1 takes ACCESS SHARE on the switch table (held to the
-- end of the transaction, so the owner's set_hooks cannot flip the flag under a caller that read it); statement 2
-- reads the row with a snapshot taken after that lock. Under READ COMMITTED it takes no row lock. Under REPEATABLE
-- READ/SERIALIZABLE the read is FOR SHARE, so a flag flipped after the caller's snapshot raises PostgreSQL's own
-- 40001 instead of returning the stale value. Missing row = off.
CREATE FUNCTION sessions.ingest_acquisition_hooks_live() RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $hooks_live$
DECLARE v_enabled boolean;
BEGIN
 PERFORM 1 FROM sessions.ingest_acquisition_hooks_switch WHERE false;
 IF current_setting('transaction_isolation')='read committed' THEN
  SELECT enabled INTO v_enabled FROM sessions.ingest_acquisition_hooks_switch WHERE singleton;
 ELSE
  SELECT enabled INTO v_enabled FROM sessions.ingest_acquisition_hooks_switch WHERE singleton FOR SHARE;
 END IF;
 RETURN coalesce(v_enabled,false);
END $hooks_live$;

-- Owner-only flag setter (no grants). ACCESS EXCLUSIVE on the switch table waits out every transaction that read
-- the flag (busy past lock_timeout = 55000 hooks_not_quiescent), so no hook straddles a flip. Turning the flag off
-- is refused while any enrollment row exists (enroll_begin holds the row FOR SHARE, so it cannot race this).
-- Update the flag only through this function.
CREATE FUNCTION sessions.ingest_acquisition_set_hooks(p_enabled boolean) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET lock_timeout='5s' AS $set_hooks$
DECLARE v_enabled boolean;
BEGIN
 IF p_enabled IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
 BEGIN
  LOCK TABLE sessions.ingest_acquisition_hooks_switch IN ACCESS EXCLUSIVE MODE;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: hooks_not_quiescent';
 END;
 SELECT enabled INTO v_enabled FROM sessions.ingest_acquisition_hooks_switch WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: hooks switch row missing';END IF;
 IF v_enabled=p_enabled THEN RETURN v_enabled;END IF;
 IF NOT p_enabled AND EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: hooks_enrolled';END IF;
 UPDATE sessions.ingest_acquisition_hooks_switch SET enabled=p_enabled,changed_at=clock_timestamp() WHERE singleton;
 RETURN p_enabled;
END $set_hooks$;

-- Sorted, distinct [source, session] pairs of a jsonb pair array (any order, duplicates allowed).
CREATE FUNCTION sessions.ingest_acquisition_sorted(p_pairs jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $sorted$
 SELECT coalesce(jsonb_agg(jsonb_build_array(s,i) ORDER BY s COLLATE "C",i COLLATE "C"),'[]'::jsonb)
 FROM (SELECT DISTINCT x->>0 s,x->>1 i FROM jsonb_array_elements(coalesce(p_pairs,'[]'::jsonb)) x WHERE x->>1 IS NOT NULL) q
$sorted$;

-- Hook-side LE + LA (§4.5): the gate, then the enrollment rows of the batch's sources FOR SHARE NOWAIT, then
-- pg_try_advisory_xact_lock_shared per enrolled session in (source, session) COLLATE "C" order. Unenrolled pairs
-- take no LA. p_exclusive is for the control functions (one pair, no gate: they read enrollment themselves).
-- With the hooks flag off the shared form returns before taking anything.
CREATE FUNCTION sessions.ingest_acquisition_lock(p_org text,p_ws text,p_pairs jsonb,p_exclusive boolean) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $lock$
DECLARE x record;
BEGIN
 IF p_exclusive THEN
  FOR x IN SELECT e->>0 s,e->>1 i FROM jsonb_array_elements(sessions.ingest_acquisition_sorted(p_pairs)) e LOOP
   IF NOT pg_try_advisory_xact_lock(sessions.ingest_acquisition_lock_key('96bulls:acquisition',p_org,p_ws,x.s,x.i)) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: session_busy';END IF;
  END LOOP;
  RETURN;
 END IF;
 IF NOT sessions.ingest_acquisition_hooks_live() THEN RETURN;END IF; -- flag off: no gate, no LA
 PERFORM sessions.ingest_acquisition_gate();
 BEGIN
  PERFORM 1 FROM sessions.ingest_acquisition_enrollment e
   WHERE e.org_id=p_org AND e.workspace_id=p_ws
    AND e.source IN(SELECT j->>0 FROM jsonb_array_elements(coalesce(p_pairs,'[]'::jsonb)) j)
   ORDER BY e.source COLLATE "C" FOR SHARE NOWAIT;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: session_busy';
 END;
 FOR x IN SELECT e->>0 s,e->>1 i FROM jsonb_array_elements(sessions.ingest_acquisition_sorted(p_pairs)) e
  WHERE EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
   WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=e->>0) LOOP
  IF NOT pg_try_advisory_xact_lock_shared(sessions.ingest_acquisition_lock_key('96bulls:acquisition',p_org,p_ws,x.s,x.i)) THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: session_busy';END IF;
 END LOOP;
END $lock$;

-- Raise a batch refusal: the first refusal's SQLSTATE and code, DETAIL = every [{source,sessionId,code}] (§5.6).
-- VOLATILE on purpose: it exists for its side effect (raising). An IMMUTABLE or STABLE function with constant
-- arguments may be evaluated once at plan time or folded, which must never happen to a refusal.
CREATE FUNCTION sessions.ingest_acquisition_refuse(p_refused jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $refuse$
DECLARE v_code text;
BEGIN
 IF p_refused IS NULL OR jsonb_array_length(p_refused)=0 THEN RETURN;END IF;
 v_code:=p_refused->0->>'code';
 RAISE EXCEPTION USING ERRCODE=CASE WHEN v_code='session_required' THEN '22023' WHEN v_code='not_owner' THEN '42501' ELSE '55000' END,
  MESSAGE='acquisition: '||v_code,DETAIL=p_refused::text;
END $refuse$;

-- §5.1 admission. Called after ingest_acquisition_lock(...,false) in the same transaction. Returns the snapshot
-- stored in ingest_claim_attempts.acquisition: [{source,session_id,owner_epoch (decimal string),grant_id}] for the
-- enrolled sessions, '[]' when the batch touches no enrolled source. Any miss rejects the whole batch.
CREATE FUNCTION sessions.ingest_acquisition_admit(p_org text,p_ws text,p_user text,p_origin text,p_pairs jsonb,
 p_null_sources jsonb,p_acq jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $admit$
DECLARE v_pairs jsonb:=sessions.ingest_acquisition_sorted(p_pairs);v_acq jsonb:=coalesce(p_acq,'[]'::jsonb);
 e jsonb;v_ps text;v_pi text;x record;o sessions.ingest_acquisition_owners%ROWTYPE;g sessions.ingest_acquisition_grants%ROWTYPE;
 v_entry jsonb;v_code text;v_refused jsonb:='[]';v_snap jsonb:='[]';
BEGIN
 IF NOT sessions.ingest_acquisition_hooks_live() THEN -- flag off: no admission (the caller already refused the key)
  IF v_acq<>'[]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: acquisition_unexpected';END IF;
  RETURN '[]'::jsonb;
 END IF;
 IF jsonb_typeof(v_acq)<>'array' OR jsonb_array_length(v_acq)>500 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
 -- Strict entry validation, never normalized (§5.1).
 FOR e IN SELECT value FROM jsonb_array_elements(v_acq) LOOP
  IF jsonb_typeof(e)<>'object'
   OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(e) k)<>ARRAY['grant','grantId','ownerEpoch','sessionId','source']
   OR EXISTS(SELECT 1 FROM jsonb_each(e) v WHERE jsonb_typeof(v.value)<>'string')
   OR e->>'grant'!~'^rhg_[0-9a-f]{64}$'
   OR e->>'grantId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR e->>'ownerEpoch'!~'^[1-9][0-9]{0,18}$' OR (e->>'ownerEpoch')::numeric>9223372036854775807
   OR (v_ps IS NOT NULL AND NOT((e->>'source') COLLATE "C">v_ps COLLATE "C"
     OR (e->>'source'=v_ps AND (e->>'sessionId') COLLATE "C">v_pi COLLATE "C"))) THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
  v_ps:=e->>'source';v_pi:=e->>'sessionId';
  IF NOT EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
     WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=e->>'source')
   OR NOT v_pairs@>jsonb_build_array(jsonb_build_array(e->>'source',e->>'sessionId')) THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: acquisition_unexpected';END IF;
 END LOOP;
 FOR x IN SELECT q->>0 s,q->>1 i FROM jsonb_array_elements(v_pairs) q
  WHERE EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
   WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=q->>0) LOOP
  SELECT * INTO o FROM sessions.ingest_acquisition_owners w
   WHERE w.org_id=p_org AND w.workspace_id=p_ws AND w.source=x.s AND w.session_id=x.i;
  IF NOT FOUND THEN o:=NULL;END IF;
  SELECT value INTO v_entry FROM jsonb_array_elements(v_acq) WHERE value->>'source'=x.s AND value->>'sessionId'=x.i;
  IF NOT FOUND THEN v_entry:=NULL;END IF;
  g:=NULL;
  IF o.grant_id IS NOT NULL THEN SELECT * INTO g FROM sessions.ingest_acquisition_grants WHERE grant_id=o.grant_id;END IF;
  v_code:=CASE
   WHEN o.state IS NULL OR o.state='unknown' THEN 'owner_unknown'
   WHEN o.state='draining' THEN 'owner_draining'
   WHEN o.state='released' THEN 'owner_released'
   WHEN o.owner_user_id IS DISTINCT FROM p_user THEN 'owner_other_principal'
   WHEN v_entry IS NULL OR g.grant_id IS NULL OR g.state<>'active'
    OR v_entry->>'grantId'<>o.grant_id::text OR v_entry->>'ownerEpoch'<>o.owner_epoch::text
    OR o.owner_origin_id IS DISTINCT FROM p_origin
    OR sessions.ingest_acquisition_grant_hash(p_org,p_ws,x.s,x.i,v_entry->>'grantId',v_entry->>'grant')<>g.grant_sha256
    THEN 'not_owner'
   WHEN g.expires_at IS NOT NULL AND g.expires_at<=clock_timestamp() THEN 'grant_expired'
  END;
  IF v_code IS NOT NULL THEN
   v_refused:=v_refused||jsonb_build_array(jsonb_build_object('source',x.s,'sessionId',x.i,'code',v_code));
  ELSE
   v_snap:=v_snap||jsonb_build_array(jsonb_build_object('source',x.s,'session_id',x.i,
    'owner_epoch',o.owner_epoch::text,'grant_id',o.grant_id::text));
  END IF;
 END LOOP;
 -- §4.7: an enrolled source's record without a session id is refused, never exempt.
 v_refused:=v_refused||coalesce((SELECT jsonb_agg(jsonb_build_object('source',s,'sessionId','','code','session_required')
   ORDER BY s COLLATE "C")
  FROM (SELECT DISTINCT y #>> '{}' s FROM jsonb_array_elements(coalesce(p_null_sources,'[]'::jsonb)) y) q
  WHERE EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
   WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=q.s)),'[]'::jsonb);
 PERFORM sessions.ingest_acquisition_refuse(v_refused);
 RETURN v_snap;
END $admit$;

-- §5.2 accepted-stage recheck (and the publish-side variant). Returns the owner_changed refusals for the enrolled
-- pairs whose admitted snapshot no longer matches: 'admit' requires active with the same epoch and grant;
-- 'publish' accepts active or draining at the admitted epoch and grant. Unenrolled pairs never refuse.
CREATE FUNCTION sessions.ingest_acquisition_fenced(p_org text,p_ws text,p_snapshot jsonb,p_pairs jsonb,p_mode text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $fenced$
BEGIN
 IF p_mode NOT IN('admit','publish') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
 IF NOT sessions.ingest_acquisition_hooks_live() THEN RETURN '[]'::jsonb;END IF; -- flag off: never refuses
 RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('source',q->>0,'sessionId',q->>1,'code','owner_changed')
   ORDER BY (q->>0) COLLATE "C",(q->>1) COLLATE "C"),'[]'::jsonb)
  FROM jsonb_array_elements(sessions.ingest_acquisition_sorted(p_pairs)) q
  WHERE EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
    WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=q->>0)
   AND NOT EXISTS(SELECT 1 FROM sessions.ingest_acquisition_owners w
    JOIN jsonb_array_elements(coalesce(p_snapshot,'[]'::jsonb)) s
     ON s->>'source'=w.source AND s->>'session_id'=w.session_id
      AND s->>'owner_epoch'=w.owner_epoch::text AND s->>'grant_id'=w.grant_id::text
    WHERE w.org_id=p_org AND w.workspace_id=p_ws AND w.source=q->>0 AND w.session_id=q->>1
     AND (w.state='active' OR (p_mode='publish' AND w.state='draining'))));
END $fenced$;

-- §5.3 publication claim: LE, then (enrolled only) LA shared, then the admitted epoch must be current and the owner
-- active or draining. Returns the head's acquisition_epoch: 0 for an unenrolled source (today's heads).
CREATE FUNCTION sessions.ingest_acquisition_publication_epoch(p_org text,p_ws text,p_source text,p_session text,p_snapshot jsonb)
RETURNS bigint LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $epoch$
DECLARE v_epoch bigint;
BEGIN
 IF NOT sessions.ingest_acquisition_hooks_live() THEN RETURN 0;END IF; -- flag off: today's heads, no gate
 PERFORM sessions.ingest_acquisition_gate();
 IF NOT EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
   WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=p_source) THEN RETURN 0;END IF;
 IF p_session IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: owner_changed',
   DETAIL=jsonb_build_array(jsonb_build_object('source',p_source,'sessionId','','code','owner_changed'))::text;END IF;
 PERFORM sessions.ingest_acquisition_lock(p_org,p_ws,jsonb_build_array(jsonb_build_array(p_source,p_session)),false);
 PERFORM sessions.ingest_acquisition_refuse(sessions.ingest_acquisition_fenced(p_org,p_ws,p_snapshot,
  jsonb_build_array(jsonb_build_array(p_source,p_session)),'publish'));
 SELECT owner_epoch INTO STRICT v_epoch FROM sessions.ingest_acquisition_owners
  WHERE org_id=p_org AND workspace_id=p_ws AND source=p_source AND session_id=p_session;
 RETURN v_epoch;
END $epoch$;

-- §5.4 publish recheck: LE, LA shared for the enrolled heads, then each owner active/draining at the head's
-- acquisitionEpoch (absent = 0, which never matches a granted owner).
CREATE FUNCTION sessions.ingest_acquisition_publish_check(p_org text,p_ws text,p_heads jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $publish$
DECLARE v_pairs jsonb;v_refused jsonb;
BEGIN
 IF NOT sessions.ingest_acquisition_hooks_live() THEN RETURN;END IF; -- flag off: no gate, no recheck
 v_pairs:=(SELECT coalesce(jsonb_agg(jsonb_build_array(h->>'source',h->>'sessionId')),'[]'::jsonb)
  FROM jsonb_array_elements(coalesce(p_heads,'[]'::jsonb)) h WHERE NOT(h->>'source'='_none' AND h->>'sessionId'='_origin'));
 PERFORM sessions.ingest_acquisition_lock(p_org,p_ws,v_pairs,false);
 v_refused:=(SELECT coalesce(jsonb_agg(jsonb_build_object('source',h->>'source','sessionId',h->>'sessionId','code','owner_changed')
   ORDER BY (h->>'source') COLLATE "C",(h->>'sessionId') COLLATE "C"),'[]'::jsonb)
  FROM jsonb_array_elements(coalesce(p_heads,'[]'::jsonb)) h
  WHERE NOT(h->>'source'='_none' AND h->>'sessionId'='_origin')
   AND EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
    WHERE n.org_id=p_org AND n.workspace_id=p_ws AND n.source=h->>'source')
   AND NOT EXISTS(SELECT 1 FROM sessions.ingest_acquisition_owners w
    WHERE w.org_id=p_org AND w.workspace_id=p_ws AND w.source=h->>'source' AND w.session_id=h->>'sessionId'
     AND w.state IN('active','draining') AND w.owner_epoch=coalesce((h->>'acquisitionEpoch')::bigint,0)));
 PERFORM sessions.ingest_acquisition_refuse(v_refused);
END $publish$;

-- §5.5 pointer guard: LE for every live write, then, for an enrolled physical source (any state), LP shared and
-- the live owner on the physical key. NULL = unenrolled (today's guard); {"refuse":true} = fail closed.
CREATE FUNCTION sessions.ingest_acquisition_pointer_owner(p_org text,p_ws text,p_harness text,p_session text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $pointer$
DECLARE o sessions.ingest_acquisition_owners%ROWTYPE;
BEGIN
 IF NOT sessions.ingest_acquisition_hooks_live() THEN RETURN NULL;END IF; -- flag off: today's guard, no gate
 PERFORM sessions.ingest_acquisition_gate();
 IF NOT EXISTS(SELECT 1 FROM sessions.ingest_acquisition_enrollment n
   WHERE n.org_id=p_org AND n.workspace_id=p_ws AND sessions.ingest_publication_component(n.source)=p_harness) THEN
  RETURN NULL;END IF;
 IF NOT pg_try_advisory_xact_lock_shared(sessions.ingest_acquisition_lock_key('96bulls:acquisition-physical',p_org,p_ws,p_harness,p_session)) THEN
  RETURN '{"refuse":true}'::jsonb;END IF;
 SELECT * INTO o FROM sessions.ingest_acquisition_owners
  WHERE org_id=p_org AND workspace_id=p_ws AND physical_source=p_harness AND physical_session=p_session
   AND state IN('active','draining');
 IF NOT FOUND THEN RETURN '{"refuse":true}'::jsonb;END IF;
 RETURN jsonb_build_object('source',o.source,'session_id',o.session_id,'owner_epoch',o.owner_epoch::text,
  'owner_user_id',o.owner_user_id,'origins',(SELECT coalesce(jsonb_agg(origin_id),'[]'::jsonb)
   FROM sessions.ingest_acquisition_grant_origins WHERE grant_id=o.grant_id));
END $pointer$;

-- ---------------------------------------------------------------------------------------------------------------
-- Control plane (§3.1). install/revoke/rebind_origin/status: bulls96_acquisition_installer only. enroll_*: no role.
-- ---------------------------------------------------------------------------------------------------------------

-- Role guard of every installer function: ingest_require_role, reported as the contract's 42501 not_installer.
CREATE FUNCTION sessions.ingest_acquisition_require_installer() RETURNS void
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $installer$
BEGIN
 PERFORM sessions.ingest_require_role('bulls96_acquisition_installer');
EXCEPTION WHEN insufficient_privilege THEN
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='acquisition: not_installer';
END $installer$;

-- The signed field list A of each request kind, in §3 order (§4.7 for rebind). Payload keys are exactly these plus
-- evidenceSha256 and requestSha256.
CREATE FUNCTION sessions.ingest_acquisition_fields(p_kind text) RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $fields$
 SELECT CASE p_kind
  WHEN 'install' THEN ARRAY['operationUuid','orgId','workspaceId','source','sessionId','revision','expectedRevision',
   'expectedOwnerEpoch','expectedPredecessorGrantId','ownerKind','ownerUserId','ownerOriginId','bindingUuid',
   'installationId','grantSha256','expiresAt','issuerKeyId']
  WHEN 'revoke' THEN ARRAY['operationUuid','orgId','workspaceId','source','sessionId','revision','targetGrantId',
   'targetOwnerEpoch','targetOwnerKind','targetBindingUuid','targetInstallationId','issuerKeyId']
  WHEN 'rebind' THEN ARRAY['operationUuid','orgId','workspaceId','source','sessionId','revision','targetGrantId',
   'targetOwnerEpoch','ownerUserId','installationId','oldOriginId','newOriginId','issuerKeyId']
 END
$fields$;

-- Byte-exact validation (never trimmed or case-folded) of an install/revoke/rebind payload, then the request digest
-- (§3 "Assertion, evidence and request digest"). Every shape failure is 22023 invalid_request; a digest mismatch is
-- 22023 request_digest_mismatch. Returns the recomputed requestSha256.
CREATE FUNCTION sessions.ingest_acquisition_request(p jsonb,p_kind text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $request$
DECLARE v_fields text[]:=sessions.ingest_acquisition_fields(p_kind);f text;v text;v_ok boolean;v_a text;v_req text;
 v_uuid constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
BEGIN
 IF v_fields IS NULL OR p IS NULL OR jsonb_typeof(p)<>'object'
  OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(p) k)
   IS DISTINCT FROM (SELECT array_agg(k ORDER BY k COLLATE "C") FROM unnest(v_fields||ARRAY['evidenceSha256','requestSha256']) k)
  OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE jsonb_typeof(e.value)<>'string') THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
 FOREACH f IN ARRAY v_fields||ARRAY['evidenceSha256','requestSha256'] LOOP
  v:=p->>f;
  IF f IN('orgId','source','sessionId','ownerUserId','ownerOriginId','oldOriginId','newOriginId','issuerKeyId','workspaceId') THEN
   BEGIN
    PERFORM sessions.ingest_identifier(p->f,f='workspaceId');v_ok:=true;
   EXCEPTION WHEN invalid_parameter_value THEN v_ok:=false;
   END;
  ELSIF f IN('operationUuid','targetGrantId') THEN v_ok:=v~v_uuid;
  ELSIF f IN('expectedPredecessorGrantId','bindingUuid','installationId','targetBindingUuid','targetInstallationId') THEN
   v_ok:=v='' OR v~v_uuid;
   IF p_kind='rebind' AND f='installationId' THEN v_ok:=v~v_uuid;END IF;
  ELSIF f IN('revision','targetOwnerEpoch') THEN
   v_ok:=v~'^[1-9][0-9]{0,18}$' AND v::numeric<=9223372036854775807;
  ELSIF f IN('expectedRevision','expectedOwnerEpoch') THEN
   v_ok:=v~'^(0|[1-9][0-9]{0,18})$' AND v::numeric<=9223372036854775807;
  ELSIF f IN('ownerKind','targetOwnerKind') THEN v_ok:=v IN('cloud','native');
  ELSIF f IN('grantSha256','evidenceSha256','requestSha256') THEN v_ok:=v~'^[0-9a-f]{64}$';
  ELSIF f='expiresAt' THEN
   IF v='' THEN v_ok:=true;
   ELSIF v!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' THEN v_ok:=false;
   ELSE
    BEGIN -- round-trips exactly (rejects 2026-02-30T00:00:00Z and 24:00:00)
     v_ok:=v=to_char(v::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
    EXCEPTION WHEN data_exception THEN v_ok:=false;
    END;
   END IF;
  ELSE v_ok:=false;
  END IF;
  IF NOT coalesce(v_ok,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
 END LOOP;
 -- Owner kind and its lineage id are exclusive (§3 grant CHECKs): cloud = bindingUuid, native = installationId.
 IF (p_kind='install' AND ((p->>'ownerKind'='cloud')<>(p->>'bindingUuid'<>'' AND p->>'installationId'='')
     OR (p->>'ownerKind'='native')<>(p->>'installationId'<>'' AND p->>'bindingUuid'='')))
  OR (p_kind='revoke' AND ((p->>'targetOwnerKind'='cloud')<>(p->>'targetBindingUuid'<>'' AND p->>'targetInstallationId'='')
     OR (p->>'targetOwnerKind'='native')<>(p->>'targetInstallationId'<>'' AND p->>'targetBindingUuid'='')))
  OR (p_kind='install' AND (p->>'expectedOwnerEpoch'='0')<>(p->>'expectedPredecessorGrantId'='')) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
 v_a:=array_to_string(ARRAY['relayhistory-acquisition-assertion-'||p_kind||'-v1']
  ||ARRAY(SELECT p->>x FROM unnest(v_fields) WITH ORDINALITY u(x,n) ORDER BY n),chr(31));
 v_req:=encode(sha256(convert_to(concat_ws(chr(31),'relayhistory-acquisition-request-v1',
  encode(sha256(convert_to(v_a,'UTF8')),'hex'),p->>'evidenceSha256'),'UTF8')),'hex');
 IF v_req<>p->>'requestSha256' THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: request_digest_mismatch';END IF;
 RETURN v_req;
END $request$;

-- §3.1 step 2: the same operationUuid with the same kind and digest replays its stored result; anything else under
-- that uuid is operation_conflict. NULL = a new operation.
CREATE FUNCTION sessions.ingest_acquisition_replay(p_op uuid,p_kind text,p_request text) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $replay$
DECLARE o sessions.ingest_acquisition_operations%ROWTYPE;
BEGIN
 SELECT * INTO o FROM sessions.ingest_acquisition_operations WHERE operation_uuid=p_op;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF o.kind<>p_kind OR o.request_sha256<>p_request THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: operation_conflict';END IF;
 RETURN o.result||'{"outcome":"replay"}'::jsonb;
END $replay$;

-- §3.1 steps 4-5 for install/revoke/rebind: LA exclusive, then LP exclusive on the physical key; never waited on.
CREATE FUNCTION sessions.ingest_acquisition_control_lock(p_org text,p_ws text,p_source text,p_session text) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,pg_temp AS $control_lock$
BEGIN
 PERFORM sessions.ingest_acquisition_lock(p_org,p_ws,jsonb_build_array(jsonb_build_array(p_source,p_session)),true);
 IF NOT pg_try_advisory_xact_lock(sessions.ingest_acquisition_lock_key('96bulls:acquisition-physical',p_org,p_ws,
   sessions.ingest_publication_component(p_source),sessions.ingest_publication_component(p_session))) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: session_busy';END IF;
END $control_lock$;

CREATE FUNCTION sessions.ingest_acquisition_install(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $install$
DECLARE v_req text;v_res jsonb;v_op uuid;v_org text;v_ws text;v_src text;v_sess text;v_psrc text;v_psess text;
 v_rev bigint;v_lineage uuid;o sessions.ingest_acquisition_owners%ROWTYPE;v_found boolean;v_latest uuid;v_con text;
BEGIN
 -- 1. Role, shape, switch, digest.
 PERFORM sessions.ingest_acquisition_require_installer();
 PERFORM sessions.ingest_acquisition_request(p,'install');
 IF NOT EXISTS(SELECT 1 FROM sessions.ingest_acquisition_switch WHERE singleton AND install_enabled) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: disabled';END IF;
 v_req:=p->>'requestSha256';v_op:=(p->>'operationUuid')::uuid;
 v_org:=p->>'orgId';v_ws:=p->>'workspaceId';v_src:=p->>'source';v_sess:=p->>'sessionId';v_rev:=(p->>'revision')::bigint;
 v_lineage:=nullif(p->>'bindingUuid','')::uuid;
 IF v_lineage IS NULL THEN v_lineage:=(p->>'installationId')::uuid;END IF;
 -- 2. Exact replay or operation_conflict.
 v_res:=sessions.ingest_acquisition_replay(v_op,'install',v_req);
 IF v_res IS NOT NULL THEN RETURN v_res;END IF;
 -- 3. An enrolled source.
 BEGIN
  PERFORM 1 FROM sessions.ingest_acquisition_enrollment
   WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND state='enrolled' FOR SHARE NOWAIT;
  v_found:=FOUND;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: session_busy';
 END;
 IF NOT v_found THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: not_enrolled';END IF;
 -- 4-5. LA exclusive, LP exclusive, the owner row FOR UPDATE, then step 2 again for a just-committed twin.
 v_psrc:=sessions.ingest_publication_component(v_src);v_psess:=sessions.ingest_publication_component(v_sess);
 PERFORM sessions.ingest_acquisition_control_lock(v_org,v_ws,v_src,v_sess);
 SELECT * INTO o FROM sessions.ingest_acquisition_owners
  WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess FOR UPDATE;
 v_found:=FOUND;
 v_res:=sessions.ingest_acquisition_replay(v_op,'install',v_req);
 IF v_res IS NOT NULL THEN RETURN v_res;END IF;
 -- 6. Revisions; a revoked operation or lineage (§4.9) or a tombstone wins over ordering.
 IF EXISTS(SELECT 1 FROM sessions.ingest_acquisition_revoked_grants WHERE grant_id=v_op)
  OR EXISTS(SELECT 1 FROM sessions.ingest_acquisition_revoked_lineages WHERE org_id=v_org AND workspace_id=v_ws
   AND source=v_src AND session_id=v_sess AND owner_kind=p->>'ownerKind' AND lineage_id=v_lineage)
  OR (v_found AND o.tombstone_revision IS NOT NULL AND v_rev<=o.tombstone_revision) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: revoked_before_install';END IF;
 IF v_found AND v_rev<=o.revision THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: stale_revision';END IF;
 IF (p->>'expectedRevision')::bigint<>coalesce(o.revision,0) OR v_rev<>(p->>'expectedRevision')::numeric+1 THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: revision_cas_lost';END IF;
 -- 7. Predecessor (§4.3).
 IF o.state='unknown' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: owner_unknown';END IF;
 IF o.state IN('active','draining') THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: handover_not_ready';END IF;
 SELECT grant_id INTO v_latest FROM sessions.ingest_acquisition_grants
  WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess ORDER BY owner_epoch DESC LIMIT 1;
 IF (p->>'expectedOwnerEpoch')::bigint<>coalesce(o.owner_epoch,0)
  OR p->>'expectedPredecessorGrantId'<>coalesce(v_latest::text,'') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: predecessor_mismatch';END IF;
 -- 8. A first owner proves the session is fresh under every user and origin.
 IF coalesce(o.owner_epoch,0)=0 AND (
  EXISTS(SELECT 1 FROM sessions.ingest_session_ownership WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess)
  OR EXISTS(SELECT 1 FROM sessions.ingest_fence_versions WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess)
  OR EXISTS(SELECT 1 FROM sessions.upload_deletions WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess)
  OR EXISTS(SELECT 1 FROM sessions.ingest_record_revisions WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess)
  OR EXISTS(SELECT 1 FROM sessions.ingest_publication_heads WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess)
  OR EXISTS(SELECT 1 FROM sessions.session_index WHERE org_id=v_org AND workspace_id=v_ws AND harness=v_psrc AND session_id=v_psess)) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: owner_unknown';END IF;
 -- 9. One live owner per physical key (terminal).
 IF EXISTS(SELECT 1 FROM sessions.ingest_acquisition_owners WHERE org_id=v_org AND workspace_id=v_ws
   AND physical_source=v_psrc AND physical_session=v_psess AND state IN('active','draining')) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: physical_collision';END IF;
 -- 10. Fence row, grant, origins and the operation result, in this transaction.
 BEGIN
  INSERT INTO sessions.ingest_acquisition_owners AS w(org_id,workspace_id,source,session_id,physical_source,physical_session,
   state,revision,owner_epoch,grant_id,owner_kind,owner_user_id,owner_origin_id)
  VALUES(v_org,v_ws,v_src,v_sess,v_psrc,v_psess,'active',v_rev,1,v_op,p->>'ownerKind',p->>'ownerUserId',p->>'ownerOriginId')
  ON CONFLICT(org_id,workspace_id,source,session_id) DO UPDATE SET state='active',revision=v_rev,
   owner_epoch=w.owner_epoch+1,grant_id=v_op,owner_kind=excluded.owner_kind,owner_user_id=excluded.owner_user_id,
   owner_origin_id=excluded.owner_origin_id,row_version=w.row_version+1,updated_at=clock_timestamp()
  RETURNING * INTO o;
 EXCEPTION WHEN unique_violation THEN
  GET STACKED DIAGNOSTICS v_con=CONSTRAINT_NAME;
  IF v_con='ingest_acquisition_owners_physical_live' THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: physical_collision';END IF;
  RAISE;
 END;
 INSERT INTO sessions.ingest_acquisition_grants(grant_id,org_id,workspace_id,source,session_id,owner_epoch,
  predecessor_grant_id,owner_kind,owner_user_id,owner_origin_id,binding_uuid,installation_id,grant_sha256,
  evidence_sha256,issuer_key_id,expires_at,state)
 VALUES(v_op,v_org,v_ws,v_src,v_sess,o.owner_epoch,v_latest,p->>'ownerKind',p->>'ownerUserId',p->>'ownerOriginId',
  nullif(p->>'bindingUuid','')::uuid,nullif(p->>'installationId','')::uuid,p->>'grantSha256',p->>'evidenceSha256',
  p->>'issuerKeyId',CASE WHEN p->>'expiresAt'='' THEN NULL ELSE (p->>'expiresAt')::timestamptz END,'active');
 INSERT INTO sessions.ingest_acquisition_grant_origins(grant_id,origin_id,revision) VALUES(v_op,p->>'ownerOriginId',v_rev);
 v_res:=jsonb_build_object('outcome','installed','grantId',v_op::text,'ownerEpoch',o.owner_epoch::text,
  'revision',o.revision::text,'state','active');
 INSERT INTO sessions.ingest_acquisition_operations(operation_uuid,kind,org_id,workspace_id,source,session_id,revision,request_sha256,result)
 VALUES(v_op,'install',v_org,v_ws,v_src,v_sess,v_rev,v_req,v_res);
 RETURN v_res;
END $install$;

CREATE FUNCTION sessions.ingest_acquisition_revoke(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $revoke$
DECLARE v_req text;v_res jsonb;v_op uuid;v_target uuid;v_org text;v_ws text;v_src text;v_sess text;v_rev bigint;
 v_kind text;v_bind uuid;v_inst uuid;v_lineage uuid;v_epoch bigint;v_outcome text;
 o sessions.ingest_acquisition_owners%ROWTYPE;g sessions.ingest_acquisition_grants%ROWTYPE;
 c sessions.ingest_acquisition_grants%ROWTYPE;rg sessions.ingest_acquisition_revoked_grants%ROWTYPE;v_found boolean;
BEGIN
 -- Install steps 1-2 (no switch: a revoke is always accepted) and 4-5.
 PERFORM sessions.ingest_acquisition_require_installer();
 PERFORM sessions.ingest_acquisition_request(p,'revoke');
 v_req:=p->>'requestSha256';v_op:=(p->>'operationUuid')::uuid;v_target:=(p->>'targetGrantId')::uuid;
 v_org:=p->>'orgId';v_ws:=p->>'workspaceId';v_src:=p->>'source';v_sess:=p->>'sessionId';v_rev:=(p->>'revision')::bigint;
 v_kind:=p->>'targetOwnerKind';v_epoch:=(p->>'targetOwnerEpoch')::bigint;
 v_bind:=nullif(p->>'targetBindingUuid','')::uuid;v_inst:=nullif(p->>'targetInstallationId','')::uuid;
 v_lineage:=coalesce(v_bind,v_inst);
 v_res:=sessions.ingest_acquisition_replay(v_op,'revoke',v_req);
 IF v_res IS NOT NULL THEN RETURN v_res;END IF;
 PERFORM sessions.ingest_acquisition_control_lock(v_org,v_ws,v_src,v_sess);
 SELECT * INTO o FROM sessions.ingest_acquisition_owners
  WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess FOR UPDATE;
 v_found:=FOUND;
 v_res:=sessions.ingest_acquisition_replay(v_op,'revoke',v_req);
 IF v_res IS NOT NULL THEN RETURN v_res;END IF;
 -- 2. An existing target must be exactly the named one.
 SELECT * INTO g FROM sessions.ingest_acquisition_grants WHERE grant_id=v_target;
 IF FOUND THEN
  IF g.org_id<>v_org OR g.workspace_id<>v_ws OR g.source<>v_src OR g.session_id<>v_sess OR g.owner_epoch<>v_epoch
   OR g.owner_kind<>v_kind OR g.binding_uuid IS DISTINCT FROM v_bind OR g.installation_id IS DISTINCT FROM v_inst THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='acquisition: target_mismatch';END IF;
  v_outcome:='superseded';
 ELSE
  -- 3. Revoke-before-install. An earlier revoke of the same uuid must name the same target.
  SELECT * INTO rg FROM sessions.ingest_acquisition_revoked_grants WHERE grant_id=v_target;
  IF FOUND AND (rg.org_id<>v_org OR rg.workspace_id<>v_ws OR rg.source<>v_src OR rg.session_id<>v_sess
   OR rg.owner_epoch<>v_epoch OR rg.owner_kind<>v_kind OR rg.binding_uuid IS DISTINCT FROM v_bind
   OR rg.installation_id IS DISTINCT FROM v_inst) THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='acquisition: target_mismatch';END IF;
  INSERT INTO sessions.ingest_acquisition_revoked_grants(grant_id,org_id,workspace_id,source,session_id,owner_epoch,
   owner_kind,binding_uuid,installation_id,revision,evidence_sha256)
  VALUES(v_target,v_org,v_ws,v_src,v_sess,v_epoch,v_kind,v_bind,v_inst,v_rev,p->>'evidenceSha256')
  ON CONFLICT(grant_id) DO NOTHING;
  v_outcome:='revoked_pending';
 END IF;
 -- 4. Lineage fence (§4.9), on both paths; drain the current grant of that lineage, whichever grant it is.
 INSERT INTO sessions.ingest_acquisition_revoked_lineages(org_id,workspace_id,source,session_id,owner_kind,lineage_id,revision)
 VALUES(v_org,v_ws,v_src,v_sess,v_kind,v_lineage,v_rev) ON CONFLICT DO NOTHING;
 IF v_found AND o.state='active' THEN
  SELECT * INTO c FROM sessions.ingest_acquisition_grants WHERE grant_id=o.grant_id;
  IF c.owner_kind=v_kind AND coalesce(c.binding_uuid,c.installation_id)=v_lineage THEN
   UPDATE sessions.ingest_acquisition_owners SET state='draining',revision=greatest(revision,v_rev),
    tombstone_revision=greatest(revision,v_rev),row_version=row_version+1,updated_at=clock_timestamp()
   WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess RETURNING * INTO o;
   UPDATE sessions.ingest_acquisition_grants SET state='draining' WHERE grant_id=c.grant_id;
   v_outcome:='draining';
  END IF;
 END IF;
 v_res:=jsonb_build_object('outcome',v_outcome,'revision',coalesce(o.revision,0)::text,
  'ownerEpoch',coalesce(o.owner_epoch,0)::text,'state',o.state);
 INSERT INTO sessions.ingest_acquisition_operations(operation_uuid,kind,org_id,workspace_id,source,session_id,revision,request_sha256,result)
 VALUES(v_op,'revoke',v_org,v_ws,v_src,v_sess,v_rev,v_req,v_res);
 RETURN v_res;
END $revoke$;

-- §4.7 native origin re-association: same installation, same user, new origin; the epoch and grant are kept.
CREATE FUNCTION sessions.ingest_acquisition_rebind_origin(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $rebind$
DECLARE v_req text;v_res jsonb;v_op uuid;v_org text;v_ws text;v_src text;v_sess text;v_rev bigint;
 o sessions.ingest_acquisition_owners%ROWTYPE;g sessions.ingest_acquisition_grants%ROWTYPE;
BEGIN
 PERFORM sessions.ingest_acquisition_require_installer();
 PERFORM sessions.ingest_acquisition_request(p,'rebind');
 v_req:=p->>'requestSha256';v_op:=(p->>'operationUuid')::uuid;
 v_org:=p->>'orgId';v_ws:=p->>'workspaceId';v_src:=p->>'source';v_sess:=p->>'sessionId';v_rev:=(p->>'revision')::bigint;
 v_res:=sessions.ingest_acquisition_replay(v_op,'rebind',v_req);
 IF v_res IS NOT NULL THEN RETURN v_res;END IF;
 PERFORM sessions.ingest_acquisition_control_lock(v_org,v_ws,v_src,v_sess);
 SELECT * INTO o FROM sessions.ingest_acquisition_owners
  WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess FOR UPDATE;
 v_res:=sessions.ingest_acquisition_replay(v_op,'rebind',v_req);
 IF v_res IS NOT NULL THEN RETURN v_res;END IF;
 IF o.grant_id IS NOT NULL THEN SELECT * INTO g FROM sessions.ingest_acquisition_grants WHERE grant_id=o.grant_id;END IF;
 IF o.state IS NULL OR o.state NOT IN('active','draining') OR o.owner_kind<>'native'
  OR o.grant_id::text<>p->>'targetGrantId' OR o.owner_epoch::text<>p->>'targetOwnerEpoch'
  OR o.owner_user_id<>p->>'ownerUserId' OR g.installation_id IS DISTINCT FROM (p->>'installationId')::uuid THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='acquisition: target_mismatch';END IF;
 IF o.owner_origin_id<>p->>'oldOriginId' THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: origin_cas_lost';END IF;
 IF v_rev<=o.revision THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='acquisition: stale_revision';END IF;
 UPDATE sessions.ingest_acquisition_owners SET revision=v_rev,owner_origin_id=p->>'newOriginId',
  row_version=row_version+1,updated_at=clock_timestamp()
 WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id=v_sess RETURNING * INTO o;
 INSERT INTO sessions.ingest_acquisition_grant_origins(grant_id,origin_id,revision)
 VALUES(o.grant_id,p->>'newOriginId',v_rev) ON CONFLICT DO NOTHING;
 v_res:=jsonb_build_object('outcome','rebound','revision',o.revision::text,'ownerEpoch',o.owner_epoch::text);
 INSERT INTO sessions.ingest_acquisition_operations(operation_uuid,kind,org_id,workspace_id,source,session_id,revision,request_sha256,result)
 VALUES(v_op,'rebind',v_org,v_ws,v_src,v_sess,v_rev,v_req,v_res);
 RETURN v_res;
END $rebind$;

-- Truthful status; never a grant hash, evidence or origin. A jsonb array in input order; bigints as decimal strings.
CREATE FUNCTION sessions.ingest_acquisition_status(p jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $status$
DECLARE v_ids jsonb;
BEGIN
 PERFORM sessions.ingest_acquisition_require_installer();
 BEGIN
  PERFORM sessions.ingest_exact_keys(p,ARRAY['orgId','workspaceId','source','sessionIds']);
  PERFORM sessions.ingest_identifier(p->'orgId',false),sessions.ingest_identifier(p->'workspaceId',true),
   sessions.ingest_identifier(p->'source',false);
  v_ids:=p->'sessionIds';
  IF jsonb_typeof(v_ids)<>'array' OR jsonb_array_length(v_ids) NOT BETWEEN 1 AND 500
   OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(v_ids) x)<>jsonb_array_length(v_ids) THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';END IF;
  PERFORM sessions.ingest_identifier(x,false) FROM jsonb_array_elements(v_ids) x;
 EXCEPTION WHEN invalid_parameter_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';
 END;
 RETURN (SELECT jsonb_agg(jsonb_build_object('sessionId',x.id,'state',o.state,'revision',coalesce(o.revision,0)::text,
   'tombstoneRevision',o.tombstone_revision::text,'ownerEpoch',coalesce(o.owner_epoch,0)::text,
   'ownerKind',o.owner_kind,'grantId',o.grant_id::text) ORDER BY x.n)
  FROM jsonb_array_elements_text(v_ids) WITH ORDINALITY x(id,n)
  LEFT JOIN sessions.ingest_acquisition_owners o ON o.org_id=p->>'orgId' AND o.workspace_id=p->>'workspaceId'
   AND o.source=p->>'source' AND o.session_id=x.id);
END $status$;

-- §4.8 enroll_begin (owner-run, no role): wait for every LE holder by updating the gate row, then mark enrolling.
-- Refused (55000 hooks_disabled) unless the hooks flag is on; the flag row is held FOR SHARE so set_hooks cannot
-- turn it off until this transaction ends.
CREATE FUNCTION sessions.ingest_acquisition_enroll_begin(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $enroll_begin$
DECLARE v_gen bigint;v_state text;
BEGIN
 BEGIN
  PERFORM sessions.ingest_exact_keys(p,ARRAY['orgId','workspaceId','source']);
  PERFORM sessions.ingest_identifier(p->'orgId',false),sessions.ingest_identifier(p->'workspaceId',true),
   sessions.ingest_identifier(p->'source',false);
 EXCEPTION WHEN invalid_parameter_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';
 END;
 IF current_setting('lock_timeout')='0' THEN PERFORM set_config('lock_timeout','5s',true);END IF;
 BEGIN
  PERFORM 1 FROM sessions.ingest_acquisition_hooks_switch WHERE singleton AND enabled FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: hooks_disabled';END IF;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: hooks_not_quiescent';
 END;
 BEGIN
  UPDATE sessions.ingest_acquisition_enrollment_gate SET generation=generation+1 WHERE singleton RETURNING generation INTO v_gen;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: enrollment_not_quiescent';
 END;
 INSERT INTO sessions.ingest_acquisition_enrollment(org_id,workspace_id,source,state)
 VALUES(p->>'orgId',p->>'workspaceId',p->>'source','enrolling') ON CONFLICT DO NOTHING;
 SELECT state INTO STRICT v_state FROM sessions.ingest_acquisition_enrollment
  WHERE org_id=p->>'orgId' AND workspace_id=p->>'workspaceId' AND source=p->>'source';
 RETURN jsonb_build_object('state',v_state,'generation',v_gen::text);
END $enroll_begin$;

-- §4.4 enroll_complete (owner-run, no role): backfill an `unknown` fence row for every session the step-8 tables,
-- the heads and session_index know for this source, record the digest of the sorted keys, set enrolled.
CREATE FUNCTION sessions.ingest_acquisition_enroll_complete(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $enroll_complete$
DECLARE e sessions.ingest_acquisition_enrollment%ROWTYPE;v_org text;v_ws text;v_src text;v_psrc text;v_keys text[];
 v_sha text;v_n bigint;
BEGIN
 BEGIN
  PERFORM sessions.ingest_exact_keys(p,ARRAY['orgId','workspaceId','source']);
  PERFORM sessions.ingest_identifier(p->'orgId',false),sessions.ingest_identifier(p->'workspaceId',true),
   sessions.ingest_identifier(p->'source',false);
 EXCEPTION WHEN invalid_parameter_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='acquisition: invalid_request';
 END;
 v_org:=p->>'orgId';v_ws:=p->>'workspaceId';v_src:=p->>'source';v_psrc:=sessions.ingest_publication_component(v_src);
 SELECT * INTO e FROM sessions.ingest_acquisition_enrollment WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='acquisition: not_enrolled';END IF;
 IF e.state='enrolled' THEN
  RETURN jsonb_build_object('state','enrolled','backfillSha256',e.backfill_sha256,'outcome','replay');END IF;
 SELECT coalesce(array_agg(k ORDER BY k COLLATE "C"),'{}') INTO v_keys FROM (
  SELECT session_id k FROM sessions.ingest_session_ownership WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src
  UNION SELECT session_id FROM sessions.ingest_fence_versions WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src
  UNION SELECT session_id FROM sessions.upload_deletions WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src
  UNION SELECT session_id FROM sessions.ingest_record_revisions WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src AND session_id IS NOT NULL
  UNION SELECT session_id FROM sessions.ingest_publication_heads WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src
  UNION SELECT session_id FROM sessions.session_index WHERE org_id=v_org AND workspace_id=v_ws AND harness=v_psrc) q;
 INSERT INTO sessions.ingest_acquisition_owners(org_id,workspace_id,source,session_id,physical_source,physical_session,
  state,revision,owner_epoch)
 SELECT v_org,v_ws,v_src,k,v_psrc,sessions.ingest_publication_component(k),'unknown',0,0 FROM unnest(v_keys) k
 ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS v_n=ROW_COUNT;
 v_sha:=encode(sha256(convert_to(coalesce((SELECT string_agg(v_src||chr(31)||k,chr(30) ORDER BY k COLLATE "C")
  FROM unnest(v_keys) k),''),'UTF8')),'hex');
 UPDATE sessions.ingest_acquisition_enrollment SET state='enrolled',backfill_sha256=v_sha,enrolled_at=clock_timestamp()
 WHERE org_id=v_org AND workspace_id=v_ws AND source=v_src;
 RETURN jsonb_build_object('state','enrolled','backfillSha256',v_sha,'backfilled',v_n::text,'outcome','enrolled');
END $enroll_complete$;
-- Design §5: each hook is CREATE OR REPLACE of its current body with only the acquisition calls inserted.

-- ingest_claim_batch_mode: current body 20261104055000_lazy_current_custody.sql:1081-1313.
CREATE OR REPLACE FUNCTION sessions.ingest_claim_batch_mode(p jsonb,p_mode text)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $claim$
DECLARE
  k record;
  v_receipt text;
  v_batch sessions.ingest_batches%ROWTYPE;
  v_state text;
  v_pairs jsonb;
  v_items jsonb;
  v_live jsonb;
  v_deleted jsonb;
  v_conflicts jsonb;
  v_count integer;
  v_stale jsonb;
  v_resets integer;
  v_fast boolean;
  v_inserted boolean;
  v_token uuid;
  v_epochs jsonb;
  v_acq jsonb;v_acq_pairs jsonb;v_nulls jsonb;
BEGIN
 IF p_mode='canonical' AND EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: explicit buffered witness required';END IF;
  PERFORM sessions.ingest_require_role('bulls96_session_ingest');
  IF p_mode NOT IN ('buffered','canonical') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid publication mode'; END IF;
  -- Flag off: an `acquisition` key is malformed input, exactly as before this migration.
  PERFORM sessions.ingest_exact_keys(CASE WHEN sessions.ingest_acquisition_hooks_live() THEN p-'acquisition' ELSE p END,
    ARRAY['tenant', 'originId', 'batchId', 'batchDigest', 'receiptId', 'sessions', 'records']);
  k := sessions.ingest_batch_key(p);
  IF jsonb_typeof(p -> 'receiptId') IS DISTINCT FROM 'string'
     OR (p ->> 'receiptId') !~ '^rhr_[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'session ingest: receiptId is malformed';
  END IF;
  v_receipt := p ->> 'receiptId';
  -- Validated and normalized once; every later step reads these values only. No
  -- temporary table: a definer function must not read objects the caller can create.
  v_pairs := (SELECT coalesce(jsonb_agg(jsonb_build_array(x.source, x.session_id)), '[]'::jsonb)
                FROM sessions.ingest_session_pairs(p -> 'sessions') AS x);
  v_items := sessions.ingest_records(p -> 'records');

  IF p_mode='canonical' AND (
    EXISTS(SELECT 1 FROM sessions.ingest_buffer_admission WHERE org_id=k.org_id) OR
    EXISTS(SELECT 1 FROM sessions.ingest_batches WHERE org_id=k.org_id AND publication_state='buffered')) THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: explicit buffered publication authority required';
  END IF;
  PERFORM sessions.ingest_lock_fences(k.org_id,k.workspace_id,k.user_id);

  -- (a) A known batch id: its receipt, a resume, or a batch-id 409. The primary key
  -- decides a race between two first claims (the insert below), not a lock.
  SELECT * INTO v_batch FROM sessions.ingest_batches AS b
   WHERE b.org_id = k.org_id AND b.workspace_id = k.workspace_id
     AND b.origin_id = k.origin_id AND b.batch_id = k.batch_id;
  IF FOUND THEN
    IF v_batch.user_id<>k.user_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='session ingest: batch owner mismatch'; END IF;
    IF v_batch.digest <> k.digest THEN
      RETURN jsonb_build_object('kind', 'batch_conflict', 'currentDigest', v_batch.digest);
    END IF;
    IF v_batch.state = 'committed' THEN
      IF v_batch.publication_state='buffered' AND v_batch.buffer_receipt_kind IS DISTINCT FROM 'suppressed'
        AND NOT EXISTS(SELECT 1 FROM sessions.ingest_buffer_outbox AS o
          LEFT JOIN sessions.ingest_stage_intents AS t ON t.stage_token=o.active_stage_token
          WHERE o.org_id=k.org_id AND o.workspace_id=k.workspace_id AND o.origin_id=k.origin_id AND o.batch_id=k.batch_id
            AND o.user_id=k.user_id AND o.digest=k.digest AND
            (o.state='erased' OR (t.receipt_state='acknowledged' AND t.cleanup_state='live'))) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: buffered receipt proof missing';
      END IF;
      RETURN jsonb_build_object('kind', 'replay', 'receiptId', v_batch.receipt_id);
    END IF;
    IF v_batch.publication_state<>p_mode THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: explicit publication transition required'; END IF;
    v_state := 'resume';
  ELSE
    v_state := 'claimed';
  END IF;

  IF p_mode='buffered' THEN PERFORM sessions.ingest_require_buffer_admission(k.org_id); END IF;

  -- (b) The batch's sessions this user deleted from this origin. As Neon 0038, their
  -- records are dropped before the revision checks (the receipt still acknowledges
  -- them), so only the rest is judged below.
  SELECT coalesce(jsonb_agg(jsonb_build_array(d.source, d.session_id)
           ORDER BY d.source COLLATE "C", d.session_id COLLATE "C"), '[]'::jsonb)
    INTO v_deleted
    FROM sessions.upload_deletions AS d
    JOIN (SELECT x.pair ->> 0 AS source, x.pair ->> 1 AS session_id FROM jsonb_array_elements(v_pairs) AS x(pair)
          UNION
          SELECT i.item ->> 'source', i.item ->> 'session_id' FROM jsonb_array_elements(v_items) AS i(item)
           WHERE i.item ->> 'session_id' IS NOT NULL) AS s
      ON s.source = d.source AND s.session_id = d.session_id
   WHERE d.org_id = k.org_id AND d.workspace_id = k.workspace_id
     AND d.user_id = k.user_id AND d.origin_id = k.origin_id;
  v_live := (SELECT coalesce(jsonb_agg(i.item ORDER BY (i.item ->> 'ord')::integer), '[]'::jsonb)
               FROM jsonb_array_elements(v_items) AS i(item)
              WHERE i.item ->> 'session_id' IS NULL
                 OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_deleted) AS d(pair)
                                 WHERE d.pair ->> 0 = i.item ->> 'source' AND d.pair ->> 1 = i.item ->> 'session_id'));

  -- (c) #250's revision rules over the committed revisions, read without a lock
  -- (the primary key serves record_id = ANY of the batch's ids). In identity order
  -- (record_id, revision, revision_id): a record whose stored revision is at or
  -- above its own is stale (a replay, whatever its digest); a NEW revision (none
  -- stored, or the stored one lower) must not be reused in the batch, by its first
  -- peer in identity order, with both another revision id and another digest.
  WITH sorted AS (
    SELECT i.*, row_number() OVER (
             ORDER BY i.record_id COLLATE "C", i.revision, i.revision_id COLLATE "C", i.ord) AS rn
      FROM jsonb_to_recordset(v_live) AS i(ord integer, source text, session_id text,
                                            record_id text, revision_id text, revision bigint, digest text)
  ), stored AS MATERIALIZED (
    SELECT c.record_id, c.revision
      FROM sessions.ingest_record_revisions AS c
     WHERE c.org_id = k.org_id AND c.workspace_id = k.workspace_id AND c.origin_id = k.origin_id
       AND c.record_id = ANY (ARRAY(SELECT DISTINCT s.record_id FROM sorted AS s))
       AND NOT(p_mode='buffered' AND EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton))
    UNION ALL
    SELECT n.record_id,n.current_revision AS revision FROM sessions.ingest_lazy_native_slots n
     WHERE p_mode='buffered' AND EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton)
      AND n.org_id=k.org_id AND n.workspace_id=k.workspace_id AND n.origin_id=k.origin_id
      AND n.current_owner=k.user_id AND n.current_revision IS NOT NULL
      -- Probe the existing global-native PK for this bounded batch. An owner
      -- index alone would scan every current record the user has ever uploaded.
      AND n.key_sha256=ANY(ARRAY(SELECT encode(sha256(convert_to(
        jsonb_build_array('global-native-custody-v1',k.org_id,k.workspace_id,k.origin_id,s.record_id)::text,'UTF8')),'hex')
        FROM sorted s))
      AND n.record_id=ANY(ARRAY(SELECT DISTINCT s.record_id FROM sorted s))
  ), peers AS (
    SELECT DISTINCT ON (s.record_id, s.revision) s.record_id, s.revision,
           s.revision_id AS peer_revision_id, s.digest AS peer_digest
      FROM sorted AS s ORDER BY s.record_id, s.revision, s.rn
  ), judged AS (
    SELECT s.rn, s.ord, s.record_id, s.revision_id, s.revision, s.digest,
           c.revision IS NOT NULL AND c.revision >= s.revision AS stale,
           (c.revision IS NULL OR c.revision < s.revision OR
             (c.revision=s.revision AND p_mode='buffered' AND EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton)))
             AND p.peer_revision_id <> s.revision_id AND p.peer_digest <> s.digest AS twin,
           p.peer_revision_id, p.peer_digest
      FROM sorted AS s
      JOIN peers AS p ON p.record_id = s.record_id AND p.revision = s.revision
      LEFT JOIN stored AS c ON c.record_id = s.record_id
  ), numbered AS (
    SELECT j.*, row_number() OVER (PARTITION BY j.twin ORDER BY j.rn) AS twin_rn FROM judged AS j
  )
  SELECT count(*) FILTER (WHERE n.twin)::integer,
         coalesce(jsonb_agg(jsonb_build_object(
           'recordId', n.record_id,
           'submittedRevisionId', n.revision_id,
           'submittedRevision', n.revision,
           'submittedDigest', n.digest,
           'currentRevisionId', n.peer_revision_id,
           'currentRevision', n.revision,
           'currentDigest', n.peer_digest) ORDER BY n.rn) FILTER (WHERE n.twin AND n.twin_rn <= 100), '[]'::jsonb),
         coalesce(jsonb_agg(n.ord ORDER BY n.ord) FILTER (WHERE n.stale), '[]'::jsonb),
         bool_and(n.stale) IS NOT FALSE
    INTO v_count, v_conflicts, v_stale, v_fast
    FROM numbered AS n;
  IF v_count > 0 THEN
    IF p_mode='buffered' AND NOT EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton) THEN
      RETURN jsonb_build_object('kind','baseline_pending'); END IF;
    RETURN jsonb_build_object('kind', 'revision_conflict', 'conflicts', v_conflicts, 'count', v_count);
  END IF;

  IF p_mode='buffered' THEN
    -- Unknown historical maxima cannot suppress accepted bytes. Potential twins
    -- above were deferred rather than incorrectly409ing a possibly stale batch.
    v_stale:='[]'::jsonb;
    v_fast:=jsonb_array_length(v_live)=0;
  END IF;

  SELECT count(*)::integer INTO v_resets FROM sessions.upload_resets AS r
   WHERE r.org_id = k.org_id AND r.workspace_id = k.workspace_id AND r.user_id = k.user_id;

  -- (d) The claim. When nothing needs writing (every record stale or deleted), the
  -- batch is committed here and the caller writes nothing (replay_fast).
  IF v_state = 'claimed' THEN
    INSERT INTO sessions.ingest_batches
           (org_id, workspace_id, origin_id, batch_id, user_id, digest, receipt_id, state, committed_at,publication_state,buffer_receipt_kind)
    VALUES (k.org_id, k.workspace_id, k.origin_id, k.batch_id, k.user_id, k.digest, v_receipt,
            CASE WHEN v_fast THEN 'committed' ELSE 'pending' END, CASE WHEN v_fast THEN now() END,p_mode,CASE WHEN p_mode='buffered' AND v_fast THEN 'suppressed' END)
    ON CONFLICT (org_id, workspace_id, origin_id, batch_id) DO NOTHING
    RETURNING true INTO v_inserted;
    IF v_inserted IS NULL THEN
      -- A concurrent first claim of this batch id won: answer as a retry would.
      SELECT * INTO v_batch FROM sessions.ingest_batches AS b
       WHERE b.org_id = k.org_id AND b.workspace_id = k.workspace_id
         AND b.origin_id = k.origin_id AND b.batch_id = k.batch_id;
      IF v_batch.user_id<>k.user_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='session ingest: batch owner mismatch'; END IF;
      IF v_batch.digest <> k.digest THEN
        RETURN jsonb_build_object('kind', 'batch_conflict', 'currentDigest', v_batch.digest);
      END IF;
      IF v_batch.state = 'committed' THEN
        RETURN jsonb_build_object('kind', 'replay', 'receiptId', v_batch.receipt_id);
      END IF;
      v_state := 'resume';
    END IF;
  END IF;
  IF v_fast THEN
    IF v_state = 'resume' THEN
      UPDATE sessions.ingest_batches AS b
         SET state = 'committed', committed_at = coalesce(b.committed_at, now()),
             buffer_receipt_kind=CASE WHEN p_mode='buffered' THEN 'suppressed' ELSE b.buffer_receipt_kind END
       WHERE b.org_id = k.org_id AND b.workspace_id = k.workspace_id
         AND b.origin_id = k.origin_id AND b.batch_id = k.batch_id AND b.digest = k.digest;
    END IF;
    v_state := 'replay_fast';
  END IF;

  -- Acquisition admission (factory acquisition owner, design §5.1): LA, then _admit, before the ownership insert.
  IF v_state IN ('claimed','resume') THEN
    v_acq_pairs:=sessions.ingest_acquisition_sorted((SELECT coalesce(jsonb_agg(jsonb_build_array(x.source,x.session_id)),'[]'::jsonb)
      FROM (SELECT q.source,q.session_id FROM sessions.ingest_session_pairs(p -> 'sessions') AS q
            UNION SELECT i.source,i.session_id FROM jsonb_to_recordset(v_items) AS i(source text,session_id text)
             WHERE i.session_id IS NOT NULL) AS x));
    v_nulls:=(SELECT coalesce(jsonb_agg(DISTINCT i.source),'[]'::jsonb) FROM jsonb_to_recordset(v_items) AS i(source text,session_id text)
      WHERE i.session_id IS NULL);
    PERFORM sessions.ingest_acquisition_lock(k.org_id,k.workspace_id,v_acq_pairs,false);
    v_acq:=sessions.ingest_acquisition_admit(k.org_id,k.workspace_id,k.user_id,k.origin_id,v_acq_pairs,v_nulls,p->'acquisition');
  END IF;
  INSERT INTO sessions.ingest_session_ownership
    (org_id,workspace_id,user_id,origin_id,source,session_id)
  SELECT k.org_id,k.workspace_id,k.user_id,k.origin_id,s.source,s.session_id
  FROM (SELECT x.source,x.session_id FROM sessions.ingest_session_pairs(p -> 'sessions') AS x
        UNION SELECT i.source,i.session_id FROM jsonb_to_recordset(v_live) AS i(source text,session_id text)
          WHERE i.session_id IS NOT NULL) AS s
  WHERE NOT EXISTS(SELECT 1 FROM sessions.upload_deletions AS d
    WHERE d.org_id=k.org_id AND d.workspace_id=k.workspace_id AND d.user_id=k.user_id
      AND d.origin_id=k.origin_id AND d.source=s.source AND d.session_id=s.session_id)
  ON CONFLICT DO NOTHING;
  IF v_state IN ('claimed','resume') THEN
    v_token:=gen_random_uuid();
    SELECT coalesce(jsonb_agg(jsonb_build_object('source',x.source,'session_id',x.session_id,'epoch',coalesce(f.epoch,0),'reset_epoch',v_resets)
      ORDER BY x.source COLLATE "C",x.session_id COLLATE "C"),'[]'::jsonb) INTO v_epochs
    FROM (SELECT q.source,q.session_id FROM sessions.ingest_session_pairs(p -> 'sessions') AS q
          UNION SELECT i.source,i.session_id FROM jsonb_to_recordset(v_items) AS i(source text,session_id text)
           WHERE i.session_id IS NOT NULL) AS x
    LEFT JOIN sessions.ingest_fence_versions AS f ON f.org_id=k.org_id AND f.workspace_id=k.workspace_id
      AND f.user_id=k.user_id AND f.origin_id=k.origin_id AND f.source=x.source AND f.session_id=x.session_id;
    INSERT INTO sessions.ingest_claim_attempts(claim_token,org_id,workspace_id,user_id,origin_id,batch_id,digest,epochs,records,reset_epoch,acquisition)
    VALUES(v_token,k.org_id,k.workspace_id,k.user_id,k.origin_id,k.batch_id,k.digest,v_epochs,v_items,v_resets,coalesce(v_acq,'[]'::jsonb));
  END IF;
  RETURN jsonb_build_object('kind', v_state, 'claimToken',v_token, 'deleted', v_deleted, 'stale', v_stale, 'resets', v_resets);
END
$claim$;

-- ingest_claim_buffered_batch: current body 20261104055000_lazy_current_custody.sql:748-786.
CREATE OR REPLACE FUNCTION sessions.ingest_claim_buffered_batch(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $buffered$
DECLARE v_generation text;v_result jsonb;v_lazy boolean;v_packet jsonb;v_known sessions.ingest_batches%ROWTYPE;v_acq jsonb;
BEGIN
 PERFORM sessions.ingest_require_role('bulls96_session_ingest');
 v_acq:=p->'acquisition';p:=p-'acquisition';
 v_lazy:=EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton);
 IF v_lazy THEN
  PERFORM sessions.ingest_exact_keys(p,ARRAY['tenant','originId','batchId','batchDigest','receiptId','sessions','records','generation','custody']);
  PERFORM sessions.ingest_lazy_begin(p,'batch');v_packet:=p->'custody';
  SELECT * INTO v_known FROM sessions.ingest_batches b WHERE b.org_id=p#>>'{tenant,orgId}' AND b.workspace_id=p#>>'{tenant,workspaceId}'
   AND b.origin_id=p->>'originId' AND b.batch_id=p->>'batchId';
  IF NOT FOUND THEN PERFORM sessions.ingest_lazy_records(p);
  ELSIF v_known.user_id=p#>>'{tenant,userId}' AND v_known.digest=p->>'batchDigest' AND v_known.state<>'committed' THEN
   PERFORM sessions.ingest_lazy_records(p);
  END IF;
  p:=p-'custody';
 ELSE
  PERFORM sessions.ingest_exact_keys(p,ARRAY['tenant','originId','batchId','batchDigest','receiptId','sessions','records','generation']);
 END IF;
 v_generation:=sessions.ingest_digest(p->'generation');
 PERFORM sessions.ingest_require_generation(v_generation);
 PERFORM sessions.ingest_require_buffer_admission(p#>>'{tenant,orgId}');
 v_result:=sessions.ingest_claim_batch_mode((p-'generation')||CASE WHEN v_acq IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('acquisition',v_acq) END,'buffered');
 IF v_result->>'kind' IN('claimed','resume') THEN
  UPDATE sessions.ingest_claim_attempts SET schema_generation=v_generation,
   source_control_version=CASE WHEN v_lazy THEN (v_packet#>>'{witness,sourceControlVersion}')::bigint END,
   source_identity_sha256=CASE WHEN v_lazy THEN v_packet#>>'{witness,sourceIdentitySha256}' END,
   source_witness_sha256=CASE WHEN v_lazy THEN v_packet->>'sourceDigest' END,
   source_processing_ranks=CASE WHEN v_lazy THEN(SELECT coalesce(jsonb_agg(e->'processingRank' ORDER BY(e->>'preparedOrd')::integer),'[]')
    FROM jsonb_array_elements(v_packet#>'{witness,records}')q(e)) END
   WHERE claim_token=(v_result->>'claimToken')::uuid AND (schema_generation IS NULL OR schema_generation=v_generation);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: claim generation collision';END IF;
 END IF;
 PERFORM sessions.ingest_require_buffer_admission(p#>>'{tenant,orgId}');
 IF v_lazy THEN v_result:=v_result||jsonb_build_object('custodyAck',
  sessions.ingest_lazy_ack(p||jsonb_build_object('custody',v_packet),'batch'));END IF;
 RETURN v_result;
END
$buffered$;

-- ingest_prepare_buffer_stage: current body 20261104055000_lazy_current_custody.sql:788-881.
CREATE OR REPLACE FUNCTION sessions.ingest_prepare_buffer_stage(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $prepare$
DECLARE k record;a sessions.ingest_claim_attempts%ROWTYPE;t sessions.ingest_stage_intents%ROWTYPE;v_generation text;
 v_key text;v_sha text;v_bytes bigint;v_groups jsonb;v_count integer;v_distinct integer;v_token uuid;v_pairs jsonb;v_fenced jsonb;
BEGIN
 PERFORM sessions.ingest_require_role('bulls96_session_ingest');
 PERFORM sessions.ingest_exact_keys(p,ARRAY['tenant','originId','batchId','batchDigest','claimToken','key','sha256','bytes','groupOrdinals','generation']);
 v_generation:=sessions.ingest_digest(p->'generation');
 PERFORM sessions.ingest_require_generation(v_generation);
 k:=sessions.ingest_batch_key(p);
 PERFORM sessions.ingest_require_buffer_admission(k.org_id);
 PERFORM sessions.ingest_lock_fences(k.org_id,k.workspace_id,k.user_id);
 PERFORM sessions.ingest_lazy_attempt((p->>'claimToken')::uuid);
 PERFORM sessions.ingest_attempt_epochs(k.org_id,k.workspace_id,k.user_id,k.origin_id,k.batch_id,k.digest,p->>'claimToken');
 SELECT * INTO a FROM sessions.ingest_claim_attempts WHERE claim_token=(p->>'claimToken')::uuid;
 IF a.schema_generation IS DISTINCT FROM v_generation
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: claim generation changed';END IF;
 IF a.reset_epoch IS NULL OR a.records IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: attempt lacks buffered proof'; END IF;
 PERFORM 1 FROM sessions.ingest_batches b WHERE b.org_id=k.org_id AND b.workspace_id=k.workspace_id
  AND b.origin_id=k.origin_id AND b.batch_id=k.batch_id AND b.user_id=k.user_id AND b.digest=k.digest
  AND b.publication_state='buffered' AND b.state='pending' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: buffered batch not pending'; END IF;
 v_key:=p->>'key';v_sha:=sessions.ingest_digest(p->'sha256');
 IF jsonb_typeof(p->'key') IS DISTINCT FROM 'string' OR octet_length(v_key) NOT BETWEEN 1 AND 2048
   OR position('/'||k.org_id||'/buffered-batches/v1/' IN v_key)=0
   OR v_key !~ ('-'||substr(encode(sha256(convert_to(p->>'claimToken','UTF8')),'hex'),1,32)||'\.staged\.ndjson\.zst$')
   OR v_key ~ '[\x01-\x1f\x7f]' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid buffered key'; END IF;
 IF jsonb_typeof(p->'bytes') IS DISTINCT FROM 'number' OR (p->>'bytes') !~ '^[1-9][0-9]{0,7}$' THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid buffered bytes';
 END IF;
 v_bytes:=(p->>'bytes')::bigint;
 IF v_bytes>16777216 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: buffered bytes exceed limit'; END IF;
 v_groups:=p->'groupOrdinals';
 IF jsonb_typeof(v_groups) IS DISTINCT FROM 'array' OR jsonb_array_length(v_groups) NOT BETWEEN 1 AND 500 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid buffered groups';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_groups) g
    WHERE jsonb_typeof(g)<>'array' OR jsonb_array_length(g) NOT BETWEEN 1 AND 500) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: invalid buffered ordinal group';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_groups) g CROSS JOIN LATERAL jsonb_array_elements(g) o
   WHERE jsonb_typeof(o)<>'number' OR o::text !~ '^(0|[1-9][0-9]{0,2})$'
      OR NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(a.records) r(ord integer) WHERE r.ord=(o::text)::int)) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: ordinal outside original claim';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_groups) g
  CROSS JOIN LATERAL (
   SELECT count(DISTINCT jsonb_build_array(r.source,r.session_id)) FILTER(WHERE r.session_id IS NOT NULL) cohorts,
          bool_or(r.session_id IS NULL) has_null,bool_or(r.session_id IS NOT NULL) has_session
    FROM jsonb_array_elements(g) o JOIN jsonb_to_recordset(a.records) r(ord integer,source text,session_id text)
      ON r.ord=(o::text)::int
  ) q WHERE q.cohorts>1 OR (q.has_null AND q.has_session)) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: buffered group mixes session owners';
 END IF;
 SELECT count(*)::int,count(DISTINCT o)::int INTO v_count,v_distinct
  FROM jsonb_array_elements(v_groups) g CROSS JOIN LATERAL jsonb_array_elements(g) o;
 IF v_count<>v_distinct OR v_count>500 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session ingest: repeated buffered ordinal'; END IF;
 IF a.reset_epoch<>(SELECT count(*) FROM sessions.upload_resets r
    WHERE r.org_id=k.org_id AND r.workspace_id=k.workspace_id AND r.user_id=k.user_id) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: reset before buffered intent';
 END IF;
 -- Cover every currently live original ordinal exactly once; original metadata
 -- remains in SQL, so scrubbed record/session ids cannot affect this decision.
 SELECT coalesce(jsonb_agg(jsonb_build_array(r.source,r.session_id)),'[]'::jsonb) INTO v_pairs
 FROM (SELECT DISTINCT source,session_id FROM jsonb_to_recordset(a.records) r(source text,session_id text)
       WHERE session_id IS NOT NULL) r;
 v_fenced:=sessions.ingest_attempt_fenced(k.org_id,k.workspace_id,k.user_id,k.origin_id,a.epochs,v_pairs);
 PERFORM sessions.ingest_acquisition_lock(k.org_id,k.workspace_id,v_pairs,false);
 PERFORM sessions.ingest_acquisition_refuse(sessions.ingest_acquisition_fenced(k.org_id,k.workspace_id,a.acquisition,v_pairs,'admit'));
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(a.records) r(ord integer,source text,session_id text)
   WHERE (r.ord IN(SELECT (o::text)::int FROM jsonb_array_elements(v_groups) g CROSS JOIN LATERAL jsonb_array_elements(g) o))
      IS DISTINCT FROM (r.session_id IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_fenced) f
          WHERE f->>0=r.source AND f->>1=r.session_id))) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: buffered ordinal coverage changed';
 END IF;
 SELECT * INTO t FROM sessions.ingest_stage_intents
  WHERE claim_token=a.claim_token AND stage_key=v_key FOR UPDATE;
 IF FOUND THEN
  IF t.stage_sha256<>v_sha OR t.stage_bytes<>v_bytes OR t.group_ordinals<>v_groups
    OR t.cleanup_state<>'live' OR t.receipt_state<>'preparing' OR t.expires_at<=clock_timestamp()
    OR t.parent_stage_token IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: buffered intent refused';
  END IF;
  PERFORM sessions.ingest_require_buffer_admission(k.org_id);
 RETURN jsonb_build_object('stageToken',t.stage_token,'expiresAt',t.expires_at);
 END IF;
 v_token:=gen_random_uuid();
 INSERT INTO sessions.ingest_stage_intents(stage_token,claim_token,org_id,workspace_id,user_id,origin_id,batch_id,digest,
   stage_key,stage_sha256,stage_bytes,group_ordinals,reset_epoch,expires_at)
 VALUES(v_token,a.claim_token,k.org_id,k.workspace_id,k.user_id,k.origin_id,k.batch_id,k.digest,
   v_key,v_sha,v_bytes,v_groups,a.reset_epoch,clock_timestamp()+interval '120 seconds')
 RETURNING * INTO t;
 PERFORM sessions.ingest_require_buffer_admission(k.org_id);
 RETURN jsonb_build_object('stageToken',t.stage_token,'expiresAt',t.expires_at);
END
$prepare$;

-- ingest_commit_buffered_batch: current body 20261104055000_lazy_current_custody.sql:883-944.
CREATE OR REPLACE FUNCTION sessions.ingest_commit_buffered_batch(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $bcommit$
DECLARE k record;a sessions.ingest_claim_attempts%ROWTYPE;t sessions.ingest_stage_intents%ROWTYPE;v_generation text;
 v_pairs jsonb;v_fenced jsonb;v_invalid boolean;v_stage uuid;
BEGIN
 PERFORM sessions.ingest_require_role('bulls96_session_ingest');
 PERFORM sessions.ingest_exact_keys(p,ARRAY['tenant','originId','batchId','batchDigest','claimToken','stageToken','generation']);
 v_generation:=sessions.ingest_digest(p->'generation');
 PERFORM sessions.ingest_require_generation(v_generation);
 k:=sessions.ingest_batch_key(p);
 PERFORM sessions.ingest_require_buffer_admission(k.org_id);
 PERFORM sessions.ingest_lock_fences(k.org_id,k.workspace_id,k.user_id);
 PERFORM sessions.ingest_lazy_attempt((p->>'claimToken')::uuid);
 PERFORM sessions.ingest_attempt_epochs(k.org_id,k.workspace_id,k.user_id,k.origin_id,k.batch_id,k.digest,p->>'claimToken');
 v_stage:=(p->>'stageToken')::uuid;
 SELECT * INTO a FROM sessions.ingest_claim_attempts WHERE claim_token=(p->>'claimToken')::uuid;
 IF a.schema_generation IS DISTINCT FROM v_generation
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: claim generation changed';END IF;
 PERFORM 1 FROM sessions.ingest_batches b WHERE b.org_id=k.org_id AND b.workspace_id=k.workspace_id
  AND b.origin_id=k.origin_id AND b.batch_id=k.batch_id AND b.user_id=k.user_id AND b.digest=k.digest
  AND b.publication_state='buffered' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session ingest: no buffered batch'; END IF;
 SELECT * INTO t FROM sessions.ingest_stage_intents WHERE stage_token=v_stage AND claim_token=a.claim_token FOR UPDATE;
 IF NOT FOUND OR t.parent_stage_token IS NOT NULL OR t.cleanup_state<>'live'
   OR (t.receipt_state='preparing' AND t.expires_at<=clock_timestamp()) THEN
  RETURN jsonb_build_object('kind','intent_invalid');
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_array(r.source,r.session_id)),'[]'::jsonb) INTO v_pairs
 FROM (SELECT DISTINCT r.source,r.session_id FROM jsonb_to_recordset(a.records) r(ord integer,source text,session_id text)
  WHERE r.session_id IS NOT NULL AND r.ord IN(
   SELECT (o::text)::int FROM jsonb_array_elements(t.group_ordinals) g CROSS JOIN LATERAL jsonb_array_elements(g) o)) r;
 v_fenced:=sessions.ingest_attempt_fenced(k.org_id,k.workspace_id,k.user_id,k.origin_id,a.epochs,v_pairs);
 v_invalid:=jsonb_array_length(v_fenced)>0 OR a.reset_epoch IS NULL OR a.reset_epoch<>(SELECT count(*) FROM sessions.upload_resets r
  WHERE r.org_id=k.org_id AND r.workspace_id=k.workspace_id AND r.user_id=k.user_id);
 IF v_invalid THEN
  UPDATE sessions.ingest_stage_intents SET cleanup_state='retired',row_version=row_version+1 WHERE stage_token=v_stage;
  RETURN jsonb_build_object('kind','intent_invalid');
 END IF;
 IF t.receipt_state='acknowledged' THEN
  IF EXISTS(SELECT 1 FROM sessions.ingest_buffer_outbox o WHERE o.org_id=k.org_id AND o.workspace_id=k.workspace_id
    AND o.origin_id=k.origin_id AND o.batch_id=k.batch_id AND o.digest=k.digest AND o.active_stage_token=v_stage) THEN
   PERFORM sessions.ingest_require_buffer_admission(k.org_id);
   RETURN jsonb_build_object('kind','committed')||CASE WHEN EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton)
  THEN jsonb_build_object('custodyAck',sessions.ingest_lazy_attempt_ack((p->>'claimToken')::uuid)) ELSE '{}'::jsonb END;
  END IF;
  RETURN jsonb_build_object('kind','intent_invalid');
 END IF;
 IF EXISTS(SELECT 1 FROM sessions.ingest_buffer_outbox o WHERE o.org_id=k.org_id AND o.workspace_id=k.workspace_id
   AND o.origin_id=k.origin_id AND o.batch_id=k.batch_id) THEN RETURN jsonb_build_object('kind','intent_invalid'); END IF;
 PERFORM sessions.ingest_acquisition_lock(k.org_id,k.workspace_id,v_pairs,false);
 PERFORM sessions.ingest_acquisition_refuse(sessions.ingest_acquisition_fenced(k.org_id,k.workspace_id,a.acquisition,v_pairs,'admit'));
 -- Receipt and durable recovery pointer are one transaction; no queue proof.
 INSERT INTO sessions.ingest_buffer_outbox(org_id,workspace_id,user_id,origin_id,batch_id,digest,active_stage_token)
 VALUES(k.org_id,k.workspace_id,k.user_id,k.origin_id,k.batch_id,k.digest,v_stage);
 UPDATE sessions.ingest_stage_intents SET receipt_state='acknowledged',row_version=row_version+1 WHERE stage_token=v_stage;
 UPDATE sessions.ingest_batches b SET state='committed',committed_at=coalesce(b.committed_at,clock_timestamp()),buffer_receipt_kind='staged'
 WHERE b.org_id=k.org_id AND b.workspace_id=k.workspace_id AND b.origin_id=k.origin_id AND b.batch_id=k.batch_id
  AND b.user_id=k.user_id AND b.digest=k.digest AND b.publication_state='buffered';
 IF clock_timestamp()>=t.expires_at THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: buffered intent expired';END IF;
 PERFORM sessions.ingest_require_buffer_admission(k.org_id);
 RETURN jsonb_build_object('kind','committed')||CASE WHEN EXISTS(SELECT 1 FROM sessions.ingest_lazy_policy WHERE singleton)
  THEN jsonb_build_object('custodyAck',sessions.ingest_lazy_attempt_ack((p->>'claimToken')::uuid)) ELSE '{}'::jsonb END;
END
$bcommit$;

-- ingest_commit_batch: current body 20261104060000_ingest_canonical_publication.sql:981-1072.
CREATE OR REPLACE FUNCTION sessions.ingest_commit_batch(p jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $commit$
DECLARE
  k record;
  v_machine text;
  v_items jsonb;
  v_claimed_at timestamptz;
  v_rearmed integer;
  v_epochs jsonb;
  v_fenced jsonb;
  v_pairs jsonb;
  v_invalidated boolean;
BEGIN
  PERFORM sessions.ingest_require_role('bulls96_session_ingest');
  IF EXISTS(SELECT 1 FROM sessions.ingest_claim_attempts a JOIN sessions.ingest_batches b
    USING(org_id,workspace_id,origin_id,batch_id)
    WHERE a.claim_token::text=p->>'claimToken' AND (b.publication_state='buffered' OR b.buffer_receipt_kind='staged')) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session ingest: buffered publication refused';
  END IF;

  PERFORM sessions.ingest_exact_keys(p,
    ARRAY['tenant', 'originId', 'batchId', 'batchDigest', 'sessions', 'records', 'machineId', 'claimToken']);
  k := sessions.ingest_batch_key(p);
  IF jsonb_typeof(p -> 'machineId') IS DISTINCT FROM 'string'
     OR (p ->> 'machineId') !~ '^srv_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'session ingest: machineId is malformed';
  END IF;
  v_machine := p ->> 'machineId';
  v_items := sessions.ingest_records(p -> 'records');
  PERFORM sessions.ingest_session_pairs(p -> 'sessions');

  PERFORM sessions.ingest_lock_fences(k.org_id,k.workspace_id,k.user_id);

  v_epochs:=sessions.ingest_attempt_epochs(k.org_id,k.workspace_id,k.user_id,k.origin_id,k.batch_id,k.digest,p->>'claimToken');
  v_pairs:=(SELECT coalesce(jsonb_agg(jsonb_build_array(x.source,x.session_id)),'[]'::jsonb)
    FROM (SELECT q.source,q.session_id FROM sessions.ingest_session_pairs(p->'sessions') AS q
          UNION SELECT i.source,i.session_id FROM jsonb_to_recordset(v_items) AS i(source text,session_id text)
            WHERE i.session_id IS NOT NULL) AS x);
  v_fenced:=sessions.ingest_attempt_fenced(k.org_id,k.workspace_id,k.user_id,k.origin_id,v_epochs,v_pairs);
  PERFORM sessions.ingest_acquisition_lock(k.org_id,k.workspace_id,v_pairs,false);
  PERFORM sessions.ingest_acquisition_refuse(sessions.ingest_acquisition_fenced(k.org_id,k.workspace_id,
    coalesce((SELECT c.acquisition FROM sessions.ingest_claim_attempts c WHERE c.claim_token=(p->>'claimToken')::uuid),'[]'::jsonb),v_pairs,'admit'));
  SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(v_fenced) AS x(pair)
    WHERE NOT EXISTS(SELECT 1 FROM sessions.upload_deletions AS d
      WHERE d.org_id=k.org_id AND d.workspace_id=k.workspace_id AND d.user_id=k.user_id
        AND d.origin_id=k.origin_id AND d.source=x.pair->>0 AND d.session_id=x.pair->>1))
    INTO v_invalidated;
  SELECT b.claimed_at INTO v_claimed_at FROM sessions.ingest_batches AS b
   WHERE b.org_id=k.org_id AND b.workspace_id=k.workspace_id AND b.origin_id=k.origin_id
     AND b.batch_id=k.batch_id AND b.digest=k.digest AND b.user_id=k.user_id FOR UPDATE;
  IF NOT v_invalidated THEN
    UPDATE sessions.ingest_batches AS b SET state='committed',committed_at=coalesce(b.committed_at,now())
     WHERE b.org_id=k.org_id AND b.workspace_id=k.workspace_id AND b.origin_id=k.origin_id
       AND b.batch_id=k.batch_id AND b.digest=k.digest AND b.user_id=k.user_id;
  END IF;

  -- The written revisions become stored: per record its highest (first in identity
  -- order), inserted, or replacing a lower one only (#250: an equal revision keeps
  -- the stored row). Rows are touched in record_id order, so two commits sharing
  -- records lock them in the same order. Idempotent.
  INSERT INTO sessions.ingest_record_revisions AS t
         (org_id, workspace_id, origin_id, record_id, revision, revision_id, digest, user_id, source, session_id)
  SELECT DISTINCT ON (i.record_id) k.org_id, k.workspace_id, k.origin_id,
         i.record_id, i.revision, i.revision_id, i.digest, k.user_id, i.source, i.session_id
    FROM jsonb_to_recordset(v_items) AS i(ord integer, source text, session_id text, record_id text,
                                          revision_id text, revision bigint, digest text)
   WHERE i.session_id IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_fenced) AS f(pair)
     WHERE f.pair->>0=i.source AND f.pair->>1=i.session_id)
   ORDER BY i.record_id, i.revision DESC, i.revision_id, i.ord
  ON CONFLICT (org_id, workspace_id, origin_id, record_id) DO UPDATE
     SET revision = EXCLUDED.revision, revision_id = EXCLUDED.revision_id,
         digest = EXCLUDED.digest, user_id = EXCLUDED.user_id, source = EXCLUDED.source,
         session_id = EXCLUDED.session_id, updated_at = now()
   WHERE EXCLUDED.revision > t.revision;

  -- The fence again: a tombstone, or a reset since the claim, that this batch's
  -- objects may have outrun. Those sessions are swept again.
  WITH reached AS (
    SELECT x.pair->>0 AS source,x.pair->>1 AS session_id FROM jsonb_array_elements(v_fenced) AS x(pair)
  ), queued AS (
    INSERT INTO sessions.upload_erasure_rearm
           (org_id, workspace_id, user_id, origin_id, machine_id, source, session_id)
    SELECT k.org_id, k.workspace_id, k.user_id, k.origin_id, v_machine, r.source, r.session_id
      FROM reached AS r
    ON CONFLICT DO NOTHING
  )
  SELECT count(*)::integer INTO v_rearmed FROM reached;
  RETURN jsonb_build_object('rearmed', v_rearmed,'invalidated',v_invalidated);
END
$commit$;

-- ingest_publication_claim: current body 20261104060000_ingest_canonical_publication.sql:179-326.
CREATE OR REPLACE FUNCTION sessions.ingest_publication_claim(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $claim$
DECLARE s sessions.ingest_stage_intents%ROWTYPE;a sessions.ingest_claim_attempts%ROWTYPE;o sessions.ingest_buffer_outbox%ROWTYPE;
 f sessions.ingest_publication_frontiers%ROWTYPE;h sessions.ingest_publication_heads%ROWTYPE;g record;r record;
 v_org text;v_ws text;v_user text;v_keyroot text;v_snapshot jsonb;v_accepted jsonb;v_seats jsonb;v_heads jsonb:='[]';v_ordinals jsonb;
 v_attempt uuid:=gen_random_uuid();v_lease uuid:=gen_random_uuid();v_gen uuid;v_source text;v_session text;v_fence bigint;
 v_physws text;v_physsource text;v_physsession text;v_machine text;v_base jsonb;v_revision bigint;v_prefix text;v_pairs jsonb;v_owner_epoch bigint;
BEGIN
 PERFORM sessions.ingest_require_role('bulls96_session_ingest');
 PERFORM sessions.ingest_exact_keys(p,ARRAY['stageToken','keyRoot','bucket','region','generation']);
 PERFORM sessions.ingest_require_generation(p->>'generation');
 v_keyroot:=p->>'keyRoot';
 IF jsonb_typeof(p->'keyRoot') IS DISTINCT FROM'string' OR v_keyroot!~'^[a-z0-9][a-z0-9-]{0,62}$'
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='publication: invalid key root';END IF;
 SELECT org_id,workspace_id,user_id INTO v_org,v_ws,v_user FROM sessions.ingest_stage_intents WHERE stage_token=(p->>'stageToken')::uuid;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: stage absent';END IF;
 PERFORM sessions.ingest_require_buffer_admission(v_org);
 PERFORM sessions.ingest_lock_fences(v_org,v_ws,v_user);
 SELECT * INTO s FROM sessions.ingest_stage_intents WHERE stage_token=(p->>'stageToken')::uuid;
 PERFORM 1 FROM sessions.ingest_batches b WHERE b.org_id=s.org_id AND b.workspace_id=s.workspace_id
  AND b.origin_id=s.origin_id AND b.batch_id=s.batch_id AND b.user_id=s.user_id AND b.digest=s.digest
  AND b.state='committed' AND b.buffer_receipt_kind='staged' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: no durable buffered receipt';END IF;
 SELECT * INTO s FROM sessions.ingest_stage_intents WHERE stage_token=s.stage_token FOR UPDATE;
 SELECT * INTO o FROM sessions.ingest_buffer_outbox b WHERE b.org_id=s.org_id AND b.workspace_id=s.workspace_id
  AND b.origin_id=s.origin_id AND b.batch_id=s.batch_id FOR UPDATE;
 IF NOT FOUND OR o.active_stage_token IS DISTINCT FROM s.stage_token OR o.state<>'buffered'
  OR s.receipt_state<>'acknowledged' OR s.cleanup_state<>'live'
  OR s.gc_lease_until>clock_timestamp() OR s.gc_replacement_stage_token IS NOT NULL
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: stage busy or changed';END IF;
 PERFORM sessions.ingest_require_buffer_admission(s.org_id);
 SELECT * INTO f FROM sessions.ingest_publication_frontiers WHERE org_id=s.org_id AND workspace_id=s.workspace_id
  AND user_id=s.user_id AND origin_id=s.origin_id AND valid_until>clock_timestamp()
  AND key_root=v_keyroot AND target_bucket=p->>'bucket' AND target_region=p->>'region' AND schema_generation=p->>'generation' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='publication: complete source frontier required';END IF;
 IF jsonb_array_length(sessions.ingest_buffer_gc_kept(s.stage_token))<>jsonb_array_length(s.group_ordinals)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: stage needs privacy GC';END IF;
 SELECT * INTO STRICT a FROM sessions.ingest_claim_attempts WHERE claim_token=s.claim_token;
 v_snapshot:=sessions.ingest_publication_revision_snapshot(s.stage_token);
 -- First durable ACK owns both the canonical order and the body decision.
 -- Losing equal-revision aliases remain auditable in the seat snapshot but
 -- can never enter an image, create a head, or poison a publication lease.
 v_seats:=sessions.ingest_receipt_seats_for_stage(s.stage_token);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(a.records)x JOIN jsonb_array_elements(v_snapshot)q ON q->>'recordId'=x->>'record_id'
  WHERE (x->>'revision')::bigint>coalesce((q#>>'{stored,revision}')::bigint,0) AND q->'stored'<>'null'::jsonb
   AND (x->>'ord')::int IN(SELECT(y::text)::int FROM jsonb_array_elements(s.group_ordinals)gg CROSS JOIN LATERAL jsonb_array_elements(gg)y)
   AND (x->>'ord')::int IN(SELECT(z->>'ord')::int FROM jsonb_array_elements(v_seats->'records')z WHERE (z->>'bodyAccepted')::boolean)
   AND NOT(x->>'session_id' IS NULL AND q#>>'{stored,session_id}' IS NULL)
   AND ROW(x->>'source',x->>'session_id') IS DISTINCT FROM ROW(q#>>'{stored,source}',q#>>'{stored,session_id}'))
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='publication: cross-scope record move requires reconciliation';END IF;
 SELECT coalesce(jsonb_agg((x->>'ord')::int ORDER BY (x->>'ord')::int),'[]') INTO v_accepted
 FROM jsonb_array_elements(a.records)x JOIN jsonb_array_elements(v_snapshot)q ON q->>'recordId'=x->>'record_id'
 WHERE (x->>'ord')::int IN(SELECT (y::text)::int FROM jsonb_array_elements(s.group_ordinals)gg CROSS JOIN LATERAL jsonb_array_elements(gg)y)
  AND (x->>'ord')::int IN(SELECT(z->>'ord')::int FROM jsonb_array_elements(v_seats->'records')z WHERE (z->>'bodyAccepted')::boolean)
  AND (x->>'revision')::bigint>coalesce((q#>>'{stored,revision}')::bigint,0);
 -- Repeat the legacy in-batch first-peer conflict predicate on the complete
 -- newly admitted set; no publication can make an invalid subset canonical.
 IF EXISTS(WITH items AS(
  SELECT x AS item,row_number()OVER(PARTITION BY x->>'record_id',x->>'revision'
    ORDER BY (x->>'revision_id') COLLATE"C",(x->>'ord')::int) rn
  FROM jsonb_array_elements(a.records)x WHERE v_accepted@>to_jsonb((x->>'ord')::int)
 ), peers AS(SELECT * FROM items WHERE rn=1)
 SELECT 1 FROM items i JOIN peers q ON i.item->>'record_id'=q.item->>'record_id' AND i.item->>'revision'=q.item->>'revision'
 WHERE i.item->>'revision_id'<>q.item->>'revision_id' AND i.item->>'digest'<>q.item->>'digest')
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='publication: new revision conflict';END IF;
 v_physws:=sessions.ingest_publication_component(s.workspace_id);
 v_machine:='srv_'||left(encode(sha256(convert_to(s.workspace_id||chr(31)||s.origin_id||chr(31)||s.user_id,'UTF8')),'hex'),32);
 FOR g IN SELECT value,ordinality-1 idx FROM jsonb_array_elements(s.group_ordinals)WITH ORDINALITY LOOP
  SELECT coalesce(jsonb_agg(y ORDER BY ordinality),'[]') INTO v_ordinals
   FROM jsonb_array_elements(g.value)WITH ORDINALITY q(y,ordinality) WHERE v_accepted@>y;
  IF jsonb_array_length(v_ordinals)=0 THEN CONTINUE;END IF;
  SELECT x->>'source' source,x->>'session_id' session_id INTO r FROM jsonb_array_elements(a.records)x
   WHERE (x->>'ord')::int=(v_ordinals->>0)::int;
  v_source:=CASE WHEN r.session_id IS NULL THEN '_none' ELSE r.source END;
  v_session:=coalesce(r.session_id,'_origin');
  v_physsource:=sessions.ingest_publication_component(v_source);v_physsession:=sessions.ingest_publication_component(v_session);
  v_fence:=0;
  IF r.session_id IS NOT NULL THEN SELECT coalesce(max(epoch),0) INTO v_fence FROM sessions.ingest_fence_versions
   WHERE org_id=s.org_id AND workspace_id=s.workspace_id AND user_id=s.user_id AND origin_id=s.origin_id
    AND source=r.source AND session_id=r.session_id;END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'96bulls:publication-pointer',s.org_id,s.workspace_id,v_physsource,v_physsession,v_machine),0))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: pointer scope busy';END IF;
  SELECT * INTO h FROM sessions.ingest_publication_heads WHERE org_id=s.org_id AND workspace_id=s.workspace_id
   AND user_id=s.user_id AND origin_id=s.origin_id AND source=v_source AND session_id=v_session FOR UPDATE;
  v_owner_epoch:=sessions.ingest_acquisition_publication_epoch(s.org_id,s.workspace_id,r.source,r.session_id,a.acquisition);
  IF NOT FOUND THEN
   SELECT to_jsonb(q),coalesce(q.revision,0) INTO v_base,v_revision FROM sessions.session_index q
    WHERE q.org_id=s.org_id AND q.workspace_id=s.workspace_id AND q.harness=v_physsource
     AND q.session_id=v_physsession AND q.machine_id=v_machine FOR UPDATE;
   v_revision:=coalesce(v_revision,0);
   IF v_base IS NOT NULL AND v_base->>'deleted_at' IS NULL AND v_base->>'user_id' IS DISTINCT FROM s.user_id
   THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='publication: legacy pointer owner mismatch';END IF;
   IF v_base->>'deleted_at' IS NOT NULL THEN v_base:=NULL;END IF;
   v_gen:=gen_random_uuid();v_prefix:=v_keyroot||'/'||s.org_id||'/upload-generations/g='||v_gen;
   INSERT INTO sessions.ingest_publication_heads(org_id,workspace_id,user_id,origin_id,source,session_id,
    physical_workspace,physical_source,physical_session,machine_id,generation,fence_epoch,reset_epoch,pointer_revision,base_pointer,state,acquisition_epoch)
   VALUES(s.org_id,s.workspace_id,s.user_id,s.origin_id,v_source,v_session,
    v_physws,v_physsource,v_physsession,v_machine,v_gen,v_fence,s.reset_epoch,v_revision,v_base,'building',v_owner_epoch) RETURNING*INTO h;
   INSERT INTO sessions.ingest_publication_generations VALUES(v_gen,v_prefix,s.org_id,s.workspace_id,s.user_id,s.origin_id,
    v_source,v_session,v_fence,s.reset_epoch,'building',clock_timestamp(),NULL,f.target_bucket,f.target_region,f.key_root);
  ELSIF h.fence_epoch<>v_fence OR h.reset_epoch<>s.reset_epoch OR h.state='retired' OR h.acquisition_epoch<>v_owner_epoch
   OR NOT EXISTS(SELECT 1 FROM sessions.ingest_publication_generations WHERE generation=h.generation AND state IN('building','live')) THEN
   UPDATE sessions.ingest_publication_generations SET state='retired',retired_at=coalesce(retired_at,clock_timestamp()) WHERE generation=h.generation;
   v_gen:=gen_random_uuid();v_prefix:=v_keyroot||'/'||s.org_id||'/upload-generations/g='||v_gen;
   UPDATE sessions.ingest_publication_heads SET generation=v_gen,fence_epoch=v_fence,reset_epoch=s.reset_epoch,acquisition_epoch=v_owner_epoch,
    state='building',current_key=NULL,current_raw_sha256=NULL,
    base_pointer=CASE WHEN h.state='building' AND h.current_key IS NULL AND h.fence_epoch=v_fence AND h.reset_epoch=s.reset_epoch
     THEN h.base_pointer ELSE NULL END,row_version=row_version+1
    WHERE org_id=h.org_id AND workspace_id=h.workspace_id AND user_id=h.user_id AND origin_id=h.origin_id
     AND source=h.source AND session_id=h.session_id RETURNING*INTO h;
   INSERT INTO sessions.ingest_publication_generations VALUES(v_gen,v_prefix,s.org_id,s.workspace_id,s.user_id,s.origin_id,
    v_source,v_session,v_fence,s.reset_epoch,'building',clock_timestamp(),NULL,f.target_bucket,f.target_region,f.key_root);
  END IF;
  SELECT prefix INTO v_prefix FROM sessions.ingest_publication_generations WHERE generation=h.generation AND state IN('building','live')
   AND target_bucket=f.target_bucket AND target_region=f.target_region AND key_root=f.key_root;
  IF NOT FOUND OR v_prefix IS DISTINCT FROM v_keyroot||'/'||s.org_id||'/upload-generations/g='||h.generation
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: generation changed';END IF;
  IF h.build_attempt_token IS NOT NULL AND h.build_lease_until>clock_timestamp() THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: another batch is building this head';
  END IF;
  UPDATE sessions.ingest_publication_heads SET build_attempt_token=v_attempt,build_lease_until=clock_timestamp()+interval'5 minutes'
   WHERE org_id=h.org_id AND workspace_id=h.workspace_id AND user_id=h.user_id AND origin_id=h.origin_id
    AND source=h.source AND session_id=h.session_id RETURNING*INTO h;
  v_heads:=v_heads||jsonb_build_array(jsonb_build_object('groupIndex',g.idx,'ordinals',v_ordinals,'generation',h.generation,'prefix',v_prefix,
   'headVersion',h.row_version::text,'revision',(h.pointer_revision+1)::text,'previousKey',h.current_key,
   'previousRawSha256',h.current_raw_sha256,'basePointer',h.base_pointer,'source',h.source,'sessionId',h.session_id,
   'physicalWorkspace',h.physical_workspace,'physicalSource',h.physical_source,'physicalSession',h.physical_session,'machineId',h.machine_id,
   'fenceEpoch',h.fence_epoch::text,'resetEpoch',h.reset_epoch::text)
   ||CASE WHEN h.acquisition_epoch>0 THEN jsonb_build_object('acquisitionEpoch',h.acquisition_epoch::text) ELSE '{}'::jsonb END);
 END LOOP;
 -- This closes the strict seed baseline BEFORE any canonical image is written.
 UPDATE sessions.ingest_batches SET publication_state='canonical' WHERE org_id=s.org_id AND workspace_id=s.workspace_id
  AND origin_id=s.origin_id AND batch_id=s.batch_id;
 UPDATE sessions.ingest_stage_intents SET row_version=row_version+1,gc_lease_version=row_version+1,
  gc_lease_token=v_lease,gc_generation=p->>'generation',gc_lease_until=clock_timestamp()+interval'5 minutes',gc_keep_groups=NULL,gc_outbox_version=o.row_version
  WHERE stage_token=s.stage_token RETURNING*INTO s;
 INSERT INTO sessions.ingest_publication_attempts(attempt_token,schema_generation,stage_token,lease_token,lease_until,stage_version,outbox_version,
  org_id,workspace_id,user_id,origin_id,batch_id,digest,accepted_ordinals,revision_snapshot,head_snapshots,frontier)
 VALUES(v_attempt,p->>'generation',s.stage_token,v_lease,s.gc_lease_until,s.row_version,o.row_version,s.org_id,s.workspace_id,s.user_id,s.origin_id,
  s.batch_id,s.digest,v_accepted,v_snapshot,v_heads,to_jsonb(f)-'valid_until'||jsonb_build_object('valid_until_epoch',extract(epoch FROM f.valid_until)));
 PERFORM sessions.ingest_require_buffer_admission(s.org_id);
 IF s.gc_lease_until<=clock_timestamp() OR f.valid_until<=clock_timestamp()
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: admission expired';END IF;
 RETURN jsonb_build_object('schemaGeneration',p->>'generation','attemptToken',v_attempt,'leaseToken',v_lease,'leaseUntil',s.gc_lease_until,
  'stageToken',s.stage_token,'stageVersion',s.row_version::text,'outboxVersion',o.row_version::text,
  'tenant',jsonb_build_object('orgId',s.org_id,'workspaceId',s.workspace_id,'userId',s.user_id),
  'originId',s.origin_id,'batchId',s.batch_id,'batchDigest',s.digest,'claimToken',s.claim_token,
  'stage',jsonb_build_object('key',s.stage_key,'sha256',s.stage_sha256,'bytes',s.stage_bytes,'groupOrdinals',s.group_ordinals),
  'records',a.records,'acceptedOrdinals',v_accepted,'receiptSeats',v_seats,'heads',v_heads);
END $claim$;

-- ingest_publication_publish: current body 20261104060000_ingest_canonical_publication.sql:626-743.
CREATE OR REPLACE FUNCTION sessions.ingest_publication_publish(p jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $publish$
DECLARE a sessions.ingest_publication_attempts%ROWTYPE;v jsonb;i sessions.ingest_publication_images%ROWTYPE;message jsonb;
 v_messages jsonb;v_message_sha text;v_expected int;v_written int;v_actual int;v_notice_count int;v_row jsonb;v_applied boolean;v_result record;
BEGIN
 PERFORM sessions.ingest_require_role('bulls96_session_ingest');
 PERFORM sessions.ingest_exact_keys(p,ARRAY['attemptToken','leaseToken','messages','generation']);
 PERFORM sessions.ingest_require_generation(p->>'generation');
 v_messages:=p->'messages';
 IF jsonb_typeof(v_messages) IS DISTINCT FROM'array' OR jsonb_array_length(v_messages)>500 OR octet_length(p::text)>16777216
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='publication: notification bounds';END IF;
 v_message_sha:=encode(sha256(convert_to(v_messages::text,'UTF8')),'hex');
 SELECT*INTO a FROM sessions.ingest_publication_attempts WHERE attempt_token=(p->>'attemptToken')::uuid;
 IF NOT FOUND OR a.lease_token IS DISTINCT FROM(p->>'leaseToken')::uuid OR a.schema_generation IS DISTINCT FROM p->>'generation'
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: unknown attempt';END IF;
 IF a.state='published' THEN
  IF a.completion_sha256 IS DISTINCT FROM v_message_sha THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: completed request differs';END IF;
  RETURN jsonb_build_object('published',true,'replay',true,'images',jsonb_array_length(a.head_snapshots),
    'records',(SELECT count(DISTINCT x->>'record_id') FROM sessions.ingest_stage_intents s JOIN sessions.ingest_claim_attempts c ON c.claim_token=s.claim_token
      CROSS JOIN LATERAL jsonb_array_elements(c.records)x WHERE s.stage_token=a.stage_token AND a.accepted_ordinals@>to_jsonb((x->>'ord')::int)),
    'eligibleSessions',(SELECT count(*) FROM jsonb_array_elements(a.head_snapshots)h WHERE NOT(h->>'source'='_none' AND h->>'sessionId'='_origin')));
 END IF;
 -- Same lock as the existing complete canonical CH projector. Never wait
 -- for a remote read while holding a user fence or publication head lock.
 FOR v IN SELECT value FROM jsonb_array_elements(a.head_snapshots)
  WHERE NOT(value->>'source'='_none' AND value->>'sessionId'='_origin') ORDER BY value->>'physicalSource' COLLATE"C",value->>'sessionId' COLLATE"C"
 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'96bulls:directory-events',a.org_id,a.workspace_id,v->>'physicalSource',v->>'sessionId'),0))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: canonical projector busy';END IF;
 END LOOP;
 a:=sessions.ingest_publication_locked(a.attempt_token,a.lease_token,p->>'generation');
 PERFORM sessions.ingest_acquisition_publish_check(a.org_id,a.workspace_id,a.head_snapshots);
 IF sessions.ingest_publication_revision_snapshot(a.stage_token) IS DISTINCT FROM a.revision_snapshot
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: complete record maxima changed';END IF;
 SELECT count(*) INTO v_actual FROM sessions.ingest_publication_images WHERE attempt_token=a.attempt_token;
 IF v_actual<>jsonb_array_length(a.head_snapshots)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: complete image set not prepared';END IF;
 SELECT count(*) INTO v_notice_count FROM jsonb_array_elements(a.head_snapshots)h WHERE NOT(h->>'source'='_none' AND h->>'sessionId'='_origin');
 IF jsonb_array_length(v_messages)<>v_notice_count OR
  (SELECT count(DISTINCT m#>>'{payload,key}')FROM jsonb_array_elements(v_messages)m)<>v_notice_count
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='publication: notification set differs';END IF;
 -- All registered manifests must match the immutable prepared byte proof. A
 -- trusted bounded caller invokes this only after exact immutable PUT ACKs.
 IF EXISTS(SELECT 1 FROM sessions.ingest_publication_images x
  LEFT JOIN sessions.ingest_publication_objects o ON o.object_key=x.manifest_key
  WHERE x.attempt_token=a.attempt_token AND(o.object_key IS NULL OR o.generation<>x.generation OR o.sha256<>x.manifest_sha256
    OR o.bytes<>x.manifest_bytes OR o.kind<>'manifest' OR o.cleanup_state<>'live'))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: manifest intent proof missing';END IF;
 -- A competing record owner/newer revision can win a unique-key wait after the
 -- preceding snapshot. Require every admitted highest record to actually apply;
 -- failure rolls back pointers/jobs/authority together.
 WITH admitted AS(
  SELECT x FROM sessions.ingest_stage_intents s JOIN sessions.ingest_claim_attempts c ON c.claim_token=s.claim_token
   CROSS JOIN LATERAL jsonb_array_elements(c.records)x
  WHERE s.stage_token=a.stage_token AND a.accepted_ordinals@>to_jsonb((x->>'ord')::int)
 ), highest AS(
  SELECT DISTINCT ON((x->>'record_id') COLLATE"C")x FROM admitted ORDER BY (x->>'record_id') COLLATE"C",(x->>'revision')::bigint DESC,(x->>'ord')::int
 )
 INSERT INTO sessions.ingest_record_revisions AS t(org_id,workspace_id,origin_id,record_id,revision,revision_id,digest,user_id,source,session_id)
 SELECT a.org_id,a.workspace_id,a.origin_id,x->>'record_id',(x->>'revision')::bigint,x->>'revision_id',x->>'digest',a.user_id,x->>'source',x->>'session_id' FROM highest
 ON CONFLICT(org_id,workspace_id,origin_id,record_id) DO UPDATE SET revision=excluded.revision,revision_id=excluded.revision_id,digest=excluded.digest,
  user_id=excluded.user_id,source=excluded.source,session_id=excluded.session_id,updated_at=clock_timestamp()
 WHERE t.user_id=excluded.user_id AND excluded.revision>t.revision;
 GET DIAGNOSTICS v_written=ROW_COUNT;
 SELECT count(DISTINCT x->>'record_id') INTO v_expected
 FROM sessions.ingest_stage_intents s JOIN sessions.ingest_claim_attempts c ON c.claim_token=s.claim_token
 CROSS JOIN LATERAL jsonb_array_elements(c.records)x WHERE s.stage_token=a.stage_token AND a.accepted_ordinals@>to_jsonb((x->>'ord')::int);
 IF v_written<>v_expected THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: admitted record lost its revision race';END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(a.head_snapshots)ORDER BY value->>'physicalSource' COLLATE"C",value->>'physicalSession' COLLATE"C" LOOP
  SELECT*INTO STRICT i FROM sessions.ingest_publication_images WHERE attempt_token=a.attempt_token AND group_index=(v->>'groupIndex')::int;
  IF NOT(v->>'source'='_none' AND v->>'sessionId'='_origin') THEN
   SELECT value INTO message FROM jsonb_array_elements(v_messages) WHERE value#>>'{payload,key}'=i.manifest_key;
   IF NOT FOUND OR message->>'v' IS DISTINCT FROM'1' OR message->>'stage' IS DISTINCT FROM'object-landed'
    OR message#>>'{ctx,orgId}' IS DISTINCT FROM a.org_id OR message#>>'{ctx,workspaceId}' IS DISTINCT FROM v->>'physicalWorkspace'
    OR message#>>'{ctx,harness}' IS DISTINCT FROM v->>'physicalSource' OR message#>>'{ctx,sessionId}' IS DISTINCT FROM v->>'physicalSession'
    OR message#>>'{ctx,machineId}' IS DISTINCT FROM v->>'machineId' OR message#>>'{ctx,traceId}' IS DISTINCT FROM lower(i.pointer_row->>'trace_id')
    OR message->>'revision' IS DISTINCT FROM i.pointer_revision::text OR message#>>'{payload,revision}' IS DISTINCT FROM i.pointer_revision::text
    OR message#>>'{payload,kind}' IS DISTINCT FROM'manifest' OR message#>>'{payload,deleted}' IS NOT NULL
    OR message#>>'{payload,provider}' IS DISTINCT FROM's3' OR message#>>'{payload,bucket}' IS DISTINCT FROM a.frontier->>'target_bucket'
    OR message#>>'{payload,scrubbed}' IS DISTINCT FROM'true'
    OR coalesce(message#>>'{payload,version}',message#>>'{payload,etag}','')=''
    OR octet_length(coalesce(message#>>'{payload,version}',message#>>'{payload,etag}'))>4096
    OR message->>'workKey' IS DISTINCT FROM i.manifest_key||'@'||coalesce(message#>>'{payload,version}',message#>>'{payload,etag}')
   THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='publication: notification differs from current image';END IF;
  ELSE message:=NULL;END IF;
  UPDATE sessions.ingest_publication_generations SET state='live'WHERE generation=i.generation AND state IN('building','live');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: generation retired';END IF;
  UPDATE sessions.ingest_publication_heads SET current_key=i.manifest_key,current_raw_sha256=i.raw_sha256,pointer_revision=i.pointer_revision,
   state='live',base_pointer=NULL,row_version=row_version+1,build_attempt_token=NULL,build_lease_until=NULL
   WHERE org_id=a.org_id AND workspace_id=a.workspace_id AND user_id=a.user_id AND origin_id=a.origin_id
    AND source=v->>'source' AND session_id=v->>'sessionId' AND generation=i.generation AND row_version=(v->>'headVersion')::bigint
    AND acquisition_epoch=coalesce((v->>'acquisitionEpoch')::bigint,0);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: head CAS lost';END IF;
  IF message IS NOT NULL THEN
   v_row:=jsonb_set(i.pointer_row,'{manifest_etag}',to_jsonb(coalesce(message#>>'{payload,etag}',message#>>'{payload,version}')));
   SELECT*INTO v_result FROM sessions.upsert_session_index(jsonb_build_array(v_row));
   IF v_result.applied IS NOT TRUE THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: pointer CAS did not apply';END IF;
   UPDATE sessions.session_index SET canonical_session_id=v->>'sessionId',canonical_machine_id=v->>'machineId'
    WHERE org_id=a.org_id AND workspace_id=a.workspace_id AND harness=v->>'physicalSource' AND session_id=v->>'physicalSession'
     AND machine_id=v->>'machineId' AND manifest_key=i.manifest_key AND revision=i.pointer_revision;
   INSERT INTO sessions.pipeline_jobs(stage,work_key,trace_id,org_id,workspace_id,session_id,machine_id,message)
   VALUES('object-landed',message->>'workKey',(message#>>'{ctx,traceId}')::uuid,a.org_id,message#>>'{ctx,workspaceId}',
    message#>>'{ctx,sessionId}',message#>>'{ctx,machineId}',message);
  END IF;
 END LOOP;
 -- "erased" here is the existing buffer-outbox state: no active buffered copy.
 -- Canonical images already hold all admitted bytes;040510 cleans this retired
 -- source object via its persistent barrier, including ambiguous old writes.
 UPDATE sessions.ingest_buffer_outbox SET active_stage_token=NULL,state='erased',row_version=row_version+1
  WHERE org_id=a.org_id AND workspace_id=a.workspace_id AND origin_id=a.origin_id AND batch_id=a.batch_id
   AND active_stage_token=a.stage_token AND row_version=a.outbox_version;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: source outbox CAS lost';END IF;
 UPDATE sessions.ingest_stage_intents SET cleanup_state='retired',row_version=row_version+1,
  gc_lease_token=NULL,gc_lease_until=NULL,gc_lease_version=NULL,gc_keep_groups=NULL WHERE stage_token=a.stage_token;
 UPDATE sessions.ingest_publication_attempts SET state='published',published_at=clock_timestamp(),completion_sha256=v_message_sha WHERE attempt_token=a.attempt_token;
 PERFORM sessions.ingest_require_buffer_admission(a.org_id);
 IF a.lease_until<=clock_timestamp() OR (a.frontier->>'valid_until_epoch')::numeric<=extract(epoch FROM clock_timestamp())
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: final acknowledgement expired';END IF;
 RETURN jsonb_build_object('published',true,'replay',false,'images',jsonb_array_length(a.head_snapshots),'records',v_written,'eligibleSessions',v_notice_count);
END $publish$;

-- ingest_publication_guard_pointer: current body 20261104060000_ingest_canonical_publication.sql:407-446.
CREATE OR REPLACE FUNCTION sessions.ingest_publication_guard_pointer() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $guard$
DECLARE r sessions.session_index%ROWTYPE;h sessions.ingest_publication_heads%ROWTYPE;v_reset bigint;v_fence bigint;v_owner jsonb;
BEGIN
 IF TG_OP='DELETE' THEN r:=OLD;ELSE r:=NEW;END IF;
 IF TG_OP<>'DELETE' AND r.deleted_at IS NULL THEN
  v_owner:=sessions.ingest_acquisition_pointer_owner(r.org_id,r.workspace_id,r.harness,r.session_id);
  IF v_owner IS NOT NULL AND (v_owner?'refuse' OR r.machine_id NOT LIKE'srv\_%' ESCAPE'\') THEN RETURN NULL;END IF;
 END IF;
 IF r.machine_id NOT LIKE'srv\_%' ESCAPE'\' THEN
  IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: pointer mutation requires fresh snapshots';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'96bulls:publication-pointer',r.org_id,r.workspace_id,r.harness,r.session_id,r.machine_id),0))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='publication: pointer mutation busy';END IF;
 SELECT * INTO h FROM sessions.ingest_publication_heads WHERE org_id=r.org_id AND workspace_id=r.workspace_id
  AND physical_source=r.harness AND physical_session=r.session_id AND machine_id=r.machine_id;
 IF NOT FOUND THEN
  IF v_owner IS NOT NULL THEN RETURN NULL;END IF;
  IF position('/upload-generations/'IN r.manifest_key)>0 THEN RETURN NULL;END IF;
  IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
 END IF;
 PERFORM 1 FROM sessions.ingest_fence_owners WHERE org_id=h.org_id AND workspace_id=h.workspace_id AND user_id=h.user_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='publication: user fence missing';END IF;
 SELECT * INTO h FROM sessions.ingest_publication_heads WHERE org_id=r.org_id AND workspace_id=r.workspace_id
  AND physical_source=r.harness AND physical_session=r.session_id AND machine_id=r.machine_id FOR UPDATE NOWAIT;
 IF h.state='retired' THEN
  IF TG_OP IN('UPDATE','DELETE') AND OLD.manifest_key=coalesce(h.current_key,h.base_pointer->>'manifest_key')
   AND (TG_OP='DELETE' OR NEW.deleted_at IS NOT NULL) THEN
   IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
  END IF;
  RETURN NULL;
 END IF;
 IF TG_OP='DELETE' OR h.state<>'live' OR r.deleted_at IS NOT NULL THEN RETURN NULL;END IF;
 SELECT count(*) INTO v_reset FROM sessions.upload_resets WHERE org_id=h.org_id AND workspace_id=h.workspace_id AND user_id=h.user_id;
 SELECT coalesce(max(epoch),0) INTO v_fence FROM sessions.ingest_fence_versions WHERE org_id=h.org_id AND workspace_id=h.workspace_id
  AND user_id=h.user_id AND origin_id=h.origin_id AND source=h.source AND session_id=h.session_id;
 IF r.user_id IS DISTINCT FROM h.user_id OR r.manifest_key IS DISTINCT FROM h.current_key
  OR r.revision<>h.pointer_revision OR encode(r.content_sha256,'hex') IS DISTINCT FROM h.current_raw_sha256
  OR h.reset_epoch<>v_reset OR h.fence_epoch<>v_fence
  OR NOT EXISTS(SELECT 1 FROM sessions.ingest_publication_generations WHERE generation=h.generation AND state='live')
  OR (v_owner IS NOT NULL AND (h.source<>v_owner->>'source' OR h.session_id<>v_owner->>'session_id'
   OR h.acquisition_epoch::text<>v_owner->>'owner_epoch' OR h.user_id<>v_owner->>'owner_user_id' OR NOT (v_owner->'origins')?h.origin_id))
 THEN RETURN NULL;END IF;
 RETURN NEW;
END $guard$;

-- Design §6: the installer may run install/revoke/rebind/status only; enroll_* and every internal are granted to
-- no role (owner-run); bulls96_session_ingest reaches the internals only through the replaced definer hooks.
REVOKE ALL ON FUNCTION sessions.ingest_acquisition_lock_key(text,text,text,text,text),
 sessions.ingest_acquisition_grant_hash(text,text,text,text,text,text),sessions.ingest_acquisition_gate(),
 sessions.ingest_acquisition_hooks_live(),sessions.ingest_acquisition_set_hooks(boolean),
 sessions.ingest_acquisition_sorted(jsonb),sessions.ingest_acquisition_lock(text,text,jsonb,boolean),
 sessions.ingest_acquisition_refuse(jsonb),sessions.ingest_acquisition_admit(text,text,text,text,jsonb,jsonb,jsonb),
 sessions.ingest_acquisition_fenced(text,text,jsonb,jsonb,text),
 sessions.ingest_acquisition_publication_epoch(text,text,text,text,jsonb),
 sessions.ingest_acquisition_publish_check(text,text,jsonb),sessions.ingest_acquisition_pointer_owner(text,text,text,text),
 sessions.ingest_acquisition_require_installer(),sessions.ingest_acquisition_fields(text),
 sessions.ingest_acquisition_request(jsonb,text),sessions.ingest_acquisition_replay(uuid,text,text),
 sessions.ingest_acquisition_control_lock(text,text,text,text),
 sessions.ingest_acquisition_install(jsonb),sessions.ingest_acquisition_revoke(jsonb),
 sessions.ingest_acquisition_rebind_origin(jsonb),sessions.ingest_acquisition_status(jsonb),
 sessions.ingest_acquisition_enroll_begin(jsonb),sessions.ingest_acquisition_enroll_complete(jsonb)
 FROM PUBLIC,anon,authenticated,service_role,bulls96_session_ingest,bulls96_session_ingest_seeder,bulls96_acquisition_installer;
GRANT USAGE ON SCHEMA sessions TO bulls96_acquisition_installer;
GRANT EXECUTE ON FUNCTION sessions.ingest_acquisition_install(jsonb),sessions.ingest_acquisition_revoke(jsonb),
 sessions.ingest_acquisition_rebind_origin(jsonb),sessions.ingest_acquisition_status(jsonb) TO bulls96_acquisition_installer;
